/*v76mod*/
;

function v50_aftermath(job, realm){
  const rk = String(realm);
  const cfg = (AFTERMATH_V50[job]||{})[rk];
  if(!cfg) return;
  if(!S.aftermath) S.aftermath = {};
  const key = job + "_" + rk;
  if(S.aftermath[key]) return;
  S.aftermath[key] = "seen";
  const rn = BREAKTHROUGH_V49.realmNames||["凡人","启灵","凝元","化意","宗师","大宗师","传奇","半神","神话"];
  writePar("","noind");
  writePar("━━ 破境回响 · 晋入"+rn[realm]+" ━━","noind flagline");
  if(cfg.title) writePar(cfg.title,"inner-voice");
  (cfg.text||[]).forEach(function(t){ writePar(t); });
  if(cfg.opts && cfg.opts.length){
    writePar("","noind");
    (cfg.opts).forEach(function(o, idx){
      const b = document.createElement("button"); b.className="opt";
      b.innerHTML = "<span class='od'>◆</span> " + o.t;
      b.onclick = function(){
        try{ clearOptions(); }catch(e){}
        if(o.gainText) writePar(o.gainText,"hint");
        if(o.follow) o.follow.forEach(function(t){ writePar(t); });
        if(o.effect) { try{ o.effect(); }catch(e){ console.error(e); } }
        try{ renderTop(); renderStats(); }catch(e){}
        const b2 = document.createElement("button"); b2.className="opt";
        b2.innerHTML = "<span class='od'>◆</span> 继续前行";
        b2.onclick = function(){ closePanel(); };
        document.getElementById("options").appendChild(b2);
      };
      document.getElementById("options").appendChild(b);
    });
  } else {
    const b = document.createElement("button"); b.className="opt";
    b.innerHTML = "<span class='od'>◆</span> 继续前行";
    b.onclick = function(){ closePanel(); };
    document.getElementById("options").appendChild(b);
  }
}

/*v49inj:bte*/
BREAKTHROUGH_V49.byJob["盗贼"] = {"guardian": {"tutor": {"name": "暗影阁执事", "bonus": 10, "rescue": 60, "desc": "在暗影阁传了二十年手艺的人。他教的第一课是：'影子不抢活。'"}, "senior": {"name": "老练窃贼", "bonus": 6, "rescue": 40, "desc": "能从你身上偷走你不自知的东西，再原样放回去。他说这叫'练手'。"}, "friend": {"name": "信得过的旧友", "bonus": 4, "rescue": 30, "desc": "知道你的身份，但从不对人说。他说：'我认的是你这个人，不是你干的活。'"}}, "place": {"sacred": {"name": "暗影阁·无影室", "bonus": 8, "crisis": -8, "desc": "四面无窗的房间，地上铺着一层细灰。执事说：'在这儿待一天，灰上能看见你自己的脚印，别人看不见。'"}, "safe": {"name": "旧阁楼", "bonus": 5, "crisis": 0, "desc": "你藏身的老地方，梁上挂着一排空钩子——你以前挂赃物的。"}, "wild": {"name": "城郊废塔", "bonus": -5, "crisis": 10, "desc": "没人来的地方，也意味着出事了没人知道。塔顶风大，视野好。"}}, "crises": [{"id": "thief_trail", "title": "被人盯上", "text": ["破境到一半，你忽然觉得有人在看你。不是直觉——是后颈的那层汗毛，一根根立了起来。你这些年练出来的东西，在告诉你：来者不善。"], "opts": [{"id": "a", "t": "不回头——先完成破境", "stat": "CON", "pass": ["你压着心跳，把最后一步走完。破境成功的刹那，你才转过身——窗外什么也没有，只有一枚钉在窗框上的飞刀，刀下压着一张纸：'改日。'", "你把纸收起来，没有追。暗影阁的规矩：不追看不见的对手。"], "fail": ["你想先破境，可背后那道眼神像针一样扎着你。你分了心，境界没成，那道视线也消失了——你连它是什么都没看见。"]}, {"id": "b", "t": "反盯回去——找到它", "stat": "AGI", "pass": ["你假装起身倒水，借着动作，把视线的来处锁定了——对面屋脊，一道黑影。你翻窗出去，追了三条街。黑影在第四条街口停住，回头，朝你点了点头，然后消失在夜色里。", "你回到阁楼，发现破境虽然中断了，但你心里那口气，比刚才更顺。暗影阁的执事后来听说，只说了一句：'追得对。'"], "fail": ["你追出去，却中了调虎离山。等你回来，阁楼里被人翻过——不丢东西，但有人在你地上用灰画了一个圈，圈里是你的名字。"]}, {"id": "c", "t": "请护法打掩护", "stat": "CHA", "pass": ["护法在窗口站了一会儿，点了根烟，往外看了几眼。那道视线退了。他回头问你：'成了？'你点了点头。他把烟掐灭：'下次，换个地方。'", "你换地方之前，在旧阁楼的梁上，留了一枚铜钱——是谢他的。"], "fail": ["护法替你挡了那道视线，自己却被盯上了。他第二天出门，被人堵在巷子里敲了一闷棍。你欠他的，从一枚铜钱，变成了一笔人情债。"]}]}, {"id": "thief_oldjob", "title": "旧案回响", "text": ["破境到一半，你忽然想起一件很多年前的旧案——你亲手做的，做得干净，没有留下任何证据。可那件案子的受害者，他家里的灯，这几年一直没熄。"], "opts": [{"id": "a", "t": "不去想——干这行，就别回头", "stat": "CON", "pass": ["你压住那个念头，把心神钉在破境上。念头挣扎了几次，见你不理，慢慢沉下去了。", "破境成了。你睁开眼，阁楼里很暗，只有窗外一盏灯还亮着——不知道是谁家的。你把它当作没看见。"], "fail": ["你压不住。那盏灯在你脑海里亮了整夜，像一只不肯闭上的眼睛。你破境失败，坐在黑暗里，第一次觉得'干净'这两个字，有点烫手。"]}, {"id": "b", "t": "回头——去那户人家看看", "stat": "AGI", "pass": ["你趁着夜色去了。那户人家的灯还亮着，窗边坐着一个老人，在灯下缝一件旧衣服。你蹲在屋顶，看了很久，最后把一枚铜钱放在他家门槛下，转身走了。", "那不是还债——是一种你自己也说不清的告别。你回到阁楼，重新坐下，这一夜，破境出奇地顺。"], "fail": ["你去了，却发现那户人家早就搬走了。灯是邻居家的。你站在空屋子前，觉得自己这些年记的账，有一笔算错了地方。你回来时，破境已经凉了。"]}, {"id": "c", "t": "告诉护法——把账翻出来看看", "stat": "CHA", "pass": ["你把那件旧案讲给护法听，讲得很干，没有修饰。他听完，沉默了一会儿，说：'你记着它，说明你还没烂透。'他顿了顿：'烂透的人，早忘了。'", "你听完这句话，破境的时候，手稳了很多。"], "fail": ["你讲给护法听，他却答不上来。干这行的，没人教过怎么处理这种事。你俩在阁楼里坐了一夜，谁也没睡，谁也没说破境的事。"]}]}, {"id": "thief_abyss", "title": "深渊低语", "text": ["破境最深处，你听见一个声音，比暗影阁的执事更懂你：'你偷了这么多年，为什么不偷点大的？'它说：'我这里有一样东西，你偷不走，也丢不掉。'"], "opts": [{"id": "a", "t": "回它——'我偷的，都是我想还的'", "stat": "SPR", "pass": ["你说：'我偷的，都是我想还的。'那声音愣了一下，像从没听过这么离谱的话。它沉默了很久，说：'你这话，比你偷过的任何东西都值钱。'它退了。", "你坐在黑暗里，觉得这句话，比暗影阁教的所有手艺都难。可你说出来了。"], "fail": ["你说不出口。因为你心里清楚，你偷过的东西里，有些你从来没想过要还。那声音看穿了，在你耳边笑了一声，退了。你坐在黑暗里，想了一夜。"]}, {"id": "b", "t": "不动声色——让它以为你没听见", "stat": "AGI", "pass": ["你假装没听见，继续破境。那声音见你不应，又说了两句，见你始终稳如磐石，自己没趣地退了。", "你睁开眼时，黑暗里还剩一缕很淡的余音。你伸手，把它像捏灭一根蜡烛一样，捏碎了。"], "fail": ["你想装没听见，却忍不住竖起了耳朵。那声音发现你在听，越说越起劲。你被它牵着走了半夜，回过神来，破境已经凉了。"]}, {"id": "c", "t": "让护法递一杯热茶", "stat": "CHA", "pass": ["你让护法递一杯热茶。茶是烫的，你在黑暗里握着，掌心暖起来。那声音见了那点热气，像见了不该见的东西，退了。", "护法什么都没问。你喝着茶，觉得黑暗也没那么黑了。"], "fail": ["茶递过来的时候，那声音吹了一口气，茶凉了。你握着凉茶，护法也感觉到了不对。你们在黑暗里坐着，谁也没说话。"]}]}], "1": {"ritual": "在细灰上不留下脚印", "ritualNote": "小偷凝元，是从'会偷'到'不留痕'的那一步。", "omens": ["你最近走夜路，脚步比以前轻了。你试着踩过一撮灰，回头一看，灰上只有极淡的一点印子。", "执事蹲下来看了看，没说话，把灰重新抹平，朝你摆了摆手：'再来。'"], "success": ["你在无影室的细灰上走了一趟。这一次，灰上一个印子也没有。你回头看了看自己的来路，什么也看不见。", "执事站在门口，看着那片干净的灰，点了点头：'行了。凝元。'你走出无影室，觉得自己轻了一两——不是体重，是痕迹。"], "fail": ["你走了三趟，灰上全是脚印。你越是想轻，脚步越重。执事在旁边看了半天，说：'你想的太多了。轻不是靠想的，是靠练的。'", "你把灰抹平，走出去时，满脚都是灰。"]}, "2": {"ritual": "从满堂宾客眼皮下'不存在'一次", "ritualNote": "化意之境，是学会'存在'和'不存在'之间的那道缝。", "omens": ["你最近发现，自己在人群里待久了，别人会下意识地忽略你。不是隐身——是你站的位置，刚好在人们视线的夹角里。", "有一天，你在酒馆坐了半个时辰，小二从你身边过了一趟，没问你点什么。你站起来，他也没觉得少了谁。"], "success": ["你在满堂宾客的宴席上，走了一圈，拿了桌上的杯盏，又放回去，没有人看你一眼。你走出门，回头看了一眼——满堂的喧闹，没有一处为你停顿。", "化意，成了。你学会了那门手艺：把自己，放进人们视线的缝里。"], "fail": ["你在宴席上走了一圈，被人叫住了：'哎，你谁啊？'你后背一紧，赔了个笑，退了出去。", "执事听了，没有骂你，只说：'你还没学会'自然'。太想让人看不见，反而显眼。'"]}, "3": {"ritual": "偷一件没人知道丢了的东西", "ritualNote": "宗师之境，是偷走'没人知道丢了'的东西——比如一个秘密，一段记忆。", "omens": ["执事把你叫去，交给你一个任务：'城西的账房先生，记得一件事，他自己不知道那件事有多要紧。你去，把它'借'回来。'", "你问：'借什么？'执事说：'他自己也说不清。你去了就知道了。'"], "success": ["你在账房先生的梦里，把那件事'借'走了——是一段他早该忘掉、却死死记住的旧事。他没有醒，没有察觉，第二天照常算他的账。", "你回到无影室，把那段记忆放在执事面前。他看了看，点了点头：'宗师。你偷的东西，开始从'物'变成'心'了。'你站了一会儿，忽然觉得这门手艺，比想象中深。"], "fail": ["你进了账房先生的梦，却被他反手抓住了手腕。他在梦里睁开眼，看着你：'我就知道，你迟早会来。'", "你退出来时，满身冷汗。执事在门口等你，什么也没说，只把门让开：'进去，再练。'"]}, "4": {"ritual": "把一件偷来的东西，物归原主", "ritualNote": "大宗师之境，是学会'还'——偷了半辈子，能还回去的，才是本事。", "omens": ["你手里有一件旧物，偷了很多年，一直没出手。不是卖不掉，是你每次想卖，都觉得它烫手。", "执事有一天看了你一眼：'留着它，你睡不着。'你承认。他问：'物主还活着吗？'你查了查——还活着。"], "success": ["你趁夜把旧物放回了原处。没有惊动物主，没有留下痕迹，像它从来没有离开过。第二天，你远远看见物主发现旧物时的表情——先是一愣，然后坐了很久。", "你没有看下去，转身走了。大宗师之境，在你学会'还'的时候，成了。你忽然明白，偷的最高境界，不是拿得走，是放得回。"], "fail": ["你去了三次，三次都没能把它放回去。不是物主守得严，是你自己——你舍不得。", "你握着那件旧物，站在夜色里，第一次觉得'贪'这个字，这么重。你没能还，境界也没能成。"]}, "5": {"ritual": "从自己手里'偷'走一件事", "ritualNote": "传奇之境，是偷走自己放不下的事——比偷任何人的都难。", "omens": ["你发现你有件事，一直放不下。你试着把它从脑子里'偷'出来，它却像生了根，越拽越紧。", "执事说：'你偷过那么多东西，没偷过自己。试试。'"], "success": ["你在无影室里坐了三天，把那件事从心里'偷'了出来。它落在地上，像一件褪了色的旧物。你看了看它，没有捡。", "第三天夜里，它化成灰，被风带走了。你站起来，觉得心里空了一块——是好事。传奇之境，成了。"], "fail": ["你偷不出来。它在你心里生了根，你越用力，它扎得越深。你坐在无影室里，第一次觉得，自己也有偷不走的东西。", "执事在门口，只说了一句：'偷不走，就放下。放不下，就背着。'你听了，坐了一夜，什么都没做成。"]}, "6": {"ritual": "替一个看不见的人，把东西还回去", "ritualNote": "半神之境，是替那些已经不在了的人，做他们没做完的事。", "omens": ["你在旧宅的墙缝里，发现一封信，封着蜡，写着一个早就死了的人的名字。", "你拆开信，读了一遍，又原样封好。那封信里的事，你知道该还给谁。"], "success": ["你花了三个月，找到那封信该去的地方，把它放在收信人的门缝下。没有署名，没有落款，像风送的。", "你在暗处，看见收信人读信时的表情——先是疑惑，然后是恍然，然后是泪。你转身走了，没有多看一眼。半神之境，成了。你偷了半辈子，终于学会'送'。"], "fail": ["你找不到收信人。那封信在你在手里放了三个月，蜡都快磨掉了。你最后把它放回墙缝里，原样封好。", "你蹲在旧宅的墙根，看着那封信，觉得自己像一封信，也找不到该去的地方。"]}, "7": {"ritual": "让自己从所有账本上消失", "ritualNote": "神话之境，是让自己'不存在'到连命运都记不住你——不是躲避，是自由。", "omens": ["你开始做梦，梦见自己站在一间大屋子里，四面墙上全是账本，每一本都记着你。", "你一本一本翻过去，从你出生那天，翻到今天。你翻到最后一页——上面空着，等着你填。"], "success": ["你提起笔，没有填，而是把那一页撕了下来。墙上的账本，一本接一本暗下去，像灯一盏接一盏灭。", "你走出那间屋子，没有回头看。外面天光大亮，你站在光里，第一次觉得，'不存在'原来可以这么轻。神话之境，成了。"], "fail": ["你翻到最后一页，提笔想写，却写不出自己的名字。你握着笔，站在空白的账本前，站了很久。", "你醒来时，手心还留着笔杆的温度。你知道，那一页还空着——它不催你，但它在等你。"]}};
BREAKTHROUGH_V49.byJob["牧师"] = {"guardian": {"tutor": {"name": "圣堂神父", "bonus": 10, "rescue": 60, "desc": "在圣堂主持了四十年的弥撒。他的祷词很旧，但他的眼神很新。"}, "senior": {"name": "苦修修士", "bonus": 6, "rescue": 40, "desc": "赤脚走遍圣城的人。他说：'路走多了，脚会替你记住神。'"}, "friend": {"name": "信你的故人", "bonus": 4, "rescue": 30, "desc": "不信神，但信你。他说：'你祷告的时候，比谁都像人。'"}}, "place": {"sacred": {"name": "圣堂·主祭坛前", "bonus": 8, "crisis": -8, "desc": "彩窗把光染成七色，落在地板上。烛火很多，风进不来。"}, "safe": {"name": "圣堂唱诗室", "bonus": 5, "crisis": 0, "desc": "平时孩子们练唱的地方。长凳上有旧歌本的压痕。"}, "wild": {"name": "城外礼拜堂废墟", "bonus": -5, "crisis": 10, "desc": "一座荒废的小礼拜堂，屋顶塌了一半。月光漏进来，照在断掉的圣像上。"}}, "crises": [{"id": "priest_doubt", "title": "信仰动摇", "text": ["破境至深处，你忽然听不见自己的祷词了。你张嘴，念出的句子像别人的话，在穹顶下散掉，没有任何回应。你站在祭坛前，第一次觉得，圣光离你那么远。"], "opts": [{"id": "a", "t": "继续念——念到听见为止", "stat": "SPR", "pass": ["你跪下来，把祷词从头念起。一遍，两遍，三遍……念到第七遍时，你的声音终于落回了自己耳朵里。不是圣光回应了你——是你回应了自己。", "你睁开眼，烛火在你面前跳了一下，像打了个招呼。你继续破境，这一次，很稳。"], "fail": ["你念到声音哑了，什么也没听见。你跪在祭坛前，觉得那盏烛火，第一次显得这么远。你没能破境，坐在圣堂里，坐到天亮。"]}, {"id": "b", "t": "问神父——圣光到底在不在", "stat": "CHA", "pass": ["你走出圣堂，问神父。他想了想，说：'我侍奉了四十年，没见过圣光。'你愣住了。他接着说：'但我在你这样的年轻人眼里，见过它。'", "你回到祭坛前，重新跪下。这一次，你没有念祷词，你说了一句自己的话。那句话落进穹顶，像落进水里，荡开一圈涟漪。破境，成了。"], "fail": ["神父答不上来。他沉默了很久，说：'你问的这个问题，我年轻时也问过。后来我不问了。'你听了，心里更空了。"]}, {"id": "c", "t": "请护法陪你跪一夜", "stat": "CHA", "pass": ["你没有念祷词，只是请护法在圣堂里陪你跪了一夜。你们谁也没说话，只有烛火偶尔爆一下灯花。", "天亮时，你站起来，腿麻了，但心里那点虚，被这一夜的沉默填满了。破境，成了。"], "fail": ["护法陪你跪了一夜，你还是觉得空。天亮时你站起来，看着晨光从彩窗漏进来，第一次觉得那光，照不到你。"]}]}, {"id": "priest_abyss", "title": "深渊低语", "text": ["烛火在破境最深处暗了一下。你听见一个声音，很温和，比任何布道都温和：'你侍奉的光，照不亮的地方，一直有人替你看。你知道的。'"], "opts": [{"id": "a", "t": "点亮烛火——'我的光，我自己点'", "stat": "SPR", "pass": ["你伸手，把暗下去的烛火重新点亮。火苗在你手边跳了跳，稳住了。你说：'我的光，我自己点。'那声音没有再说第二遍。", "烛火在你手里亮了一整夜。你数了数，一共亮了三次——每一次，都是你心里的一关。"], "fail": ["你伸手点烛，火苗却在你指尖躲开。你点了三次，它暗了三次。那声音在你身后，低低地叹了一声。"]}, {"id": "b", "t": "翻出旧圣水——倒进烛台", "stat": "CON", "pass": ["你从怀里摸出一小瓶旧圣水，倒进烛台。火苗蹿了一下，又稳住了——这一次，它亮得比刚才久。", "那声音没有退，但也没有再说话。你守着那盏烛火，像守着一个你信了很久的东西。"], "fail": ["圣水倒进去，火苗却'噗'地一声，灭了。你握着空瓶，站在黑暗里，那声音没有笑，只是安静地等着。"]}, {"id": "c", "t": "请护法诵一段旧圣言", "stat": "CHA", "pass": ["护法在门外诵了一段圣言，是圣堂最旧的那段。声音不高，但很稳。那声音听了半句，就静了。", "圣言停了，烛火还亮着。你听见护法在门外说：'好了，继续。'你点了点头，重新闭上眼。"], "fail": ["护法诵了圣言，那声音却笑了：'借来的墙，挡不住借来的火。'你心里一沉——它说得对。"]}]}, {"id": "priest_wound", "title": "旧伤复发", "text": ["破境到一半，你胸口那道旧伤忽然疼起来——是你很多年前为救人留下的。疼得不是伤口，是那些年你没能救回来的人。"], "opts": [{"id": "a", "t": "按住伤口——'疼，但我知道为什么疼'", "stat": "CON", "pass": ["你按住胸口那道疤，疼得很实。你说：'疼，但我知道为什么疼。'这句话比任何祷词都管用——疼痛在你手下慢慢平息，像一头听懂人话的兽。", "破境成了。你松开手，那道疤还在，但你知道，它已经不能再左右你了。"], "fail": ["你按住伤口，却止不住那些记忆。你跪在祭坛前，一个个念出没能救回来的人的名字，念到天亮，破境也没成。"]}, {"id": "b", "t": "为没能救回的人，补一场弥撒", "stat": "SPR", "pass": ["你在祭坛前，为那些没能救回来的人，补了一场弥撒。没有别人来，只有你和烛火。你念完最后一句，觉得胸口那道疤，松了一点。", "破境成了。你站起来，觉得那场弥撒，比很多场人满为患的，都更值得。"], "fail": ["你念到一半，念不下去。那些名字太沉，你扶着祭坛，站了很久，最后还是没能念完。你没能破境，但那场弥撒，你记了很久。"]}, {"id": "c", "t": "把伤口给护法看", "stat": "CHA", "pass": ["你把伤口给护法看。他看了看，没有安慰你，只说：'这疤，救过几条命？'你说：'三条。'他说：'那就值了。'", "你听完这句话，心里的疼，忽然轻了一点。破境，成了。"], "fail": ["护法看了伤口，没有说话。他沉默的样子，让你知道，有些伤，不是说出来就能好的。你没能破境，坐在圣堂里，坐到烛火燃尽。"]}]}], "1": {"ritual": "第一次独自完成一场晨祷", "ritualNote": "信徒凝元，是从'跟着念'到'自己念'的那一步。", "omens": ["你最近在晨祷时，总能听见自己的声音比别人的慢半拍。不是跟不上，是你开始在意那些字的意思了。", "神父有一天让你留下：'明天，晨祷由你来。'"], "success": ["你站在圣堂里，独自完成了一场晨祷。没有人领，没有人应，你的声音在穹顶下荡开，又落回你耳朵里。你念到最后一句，觉得那句话说得很顺——像它不是从你嘴里出来的，是从你心里出来的。", "你走出圣堂时，神父站在门口，朝你点了点头。凝元，成了。"], "fail": ["你念到一半，忘了词。你站在祭坛前，满堂的空凳子看着你。你磕磕绊绊念完，走出圣堂，脸烧得厉害。", "神父没有笑话你，只说：'忘了词，说明你开始认真了。'你听了，心里好受了一点。"]}, "2": {"ritual": "治好一个不肯信你的人", "ritualNote": "化意之境，是神术第一次在'不信的人'身上生效。", "omens": ["圣堂门口来了一个伤者，死活不肯进门：'你们的神，救不了我。'他身上的伤很重，血渗过布条。", "你站在门口，看了他一会儿，说：'你信不信，跟我治不治你，是两回事。'"], "success": ["你蹲下来，在他不肯信的眼底，替他把伤治了。圣光落在他伤口上时，他没有看光，只看你的手。", "伤好了，他站起来，走了两步，回头看你一眼，什么也没说。你蹲在原地，觉得那一眼，比一句'谢谢'还值。化意，成了。"], "fail": ["你在他不肯信的眼底，神术失了效。圣光落在伤口上，像落在石头上，滑开了。你试了三次，他嗤笑一声，自己走了。", "你蹲在门口，看着他的背影，第一次知道：有些伤口，圣光照不进去。"]}, "3": {"ritual": "替一个临终的人，守住最后一夜", "ritualNote": "宗师之境，是学会守在'什么都留不住'的地方，一步不退。", "omens": ["圣堂收留了一个重病的人，医生说熬不过今夜。他抓住你的手，说：'别走。'", "你点了点头，在床边坐下来。烛火把你们两个人的影子，投在墙上。"], "success": ["你守了一夜。他睡睡醒醒，醒了就跟你说话，说了一辈子没跟人说的话。天亮前，他安静地走了，手还握着你的。", "你把手抽出来，替他合上眼睛。你走出房间，晨光正好照在圣堂的彩窗上。宗师之境，在你守住那一夜的时候，成了。"], "fail": ["你守到半夜，实在撑不住，出去倒了一杯水。回来时，他已经走了。杯子摔在地上，水洒了一地。", "你跪在床前，很久没有起来。你没能陪他到最后——那一夜，成了你心里一道不深的印子。"]}, "4": {"ritual": "把圣水送给一个不需要的人", "ritualNote": "大宗师之境，是学会'不施舍'——有些礼物，送出去之前，先得想清楚对方要不要。", "omens": ["你带着圣水，去看望一个落魄的老兵。他看见你手里的圣水瓶，笑了一下：'你们圣堂的人，就爱给人送这个。'", "他把瓶子推开：'我不需要这个。我需要有人听我说说话。'"], "success": ["你把圣水瓶收回去，在他对面坐下来。他讲了一下午，你听了一下午。临走时，他说：'你比圣水有用。'", "你走在回圣堂的路上，觉得这句话，比任何谢礼都重。大宗师之境，在你学会'听'的时候，成了。"], "fail": ["你还是把圣水留给了他。他收下了，没有用，也没有扔，只是放在桌角。你走的时候，回头看了一眼——那瓶圣水，和他桌上的旧酒壶摆在一起，像两个不认识的人。", "你回到圣堂，神父问你怎么样，你只说：'我送错东西了。'"]}, "5": {"ritual": "在无人看见的地方，行一次善", "ritualNote": "传奇之境，是做一件没有人知道的善事——连被帮的人，都不知道你是谁。", "omens": ["你路过城西，看见一家人门前挂着白幡——是丧事。家里只剩一个孩子，蹲在门槛上，小脸冻得通红。", "你站了一会儿，没有进去。你把手里的钱袋，悄悄放在门缝里，敲了敲门，走了。"], "success": ["三天后，你路过那户人家，看见那孩子穿上了新棉袄，蹲在门槛上晒太阳。你不知道那是不是你钱袋的功劳，但你心里，比做了一场弥撒还亮堂。", "传奇之境，成了。你没有留下名字，也不需要留下——善事做完了，它自己会记得。"], "fail": ["你把钱袋放进门缝，却被邻家的大人看见，追出来还给你：'你是圣堂的人吧？收回去吧，我们自己能行。'", "你握着被退还的钱袋，站在巷子里，第一次知道：有些善，送不出去，不是你不够诚，是时机不对。"]}, "6": {"ritual": "在圣光与深渊之间，站住", "ritualNote": "半神之境，是亲眼看过深渊，还能站在圣光这边——不是没被诱惑，是看完之后，还是选了这边。", "omens": ["神父带你去了一处地窖，让你看一样东西——是一块从深渊边缘带回来的石头，黑得发亮，像一只闭着的眼睛。", "他把它放在你面前，没有收走：'你看着它，想多久都行。'"], "success": ["你看着那块石头，看了三天。第三天，你把它放回盒子里，盖上。神父问：'看见了什么？'你说：'看见了它想让我看见的东西。'他说：'然后呢？'你说：'然后，我还是我。'", "半神之境，成了。你走出地窖，阳光落在你肩上，你觉得那光，从来没有这么暖过。"], "fail": ["你看着那块石头，看了三天。第三天夜里，你梦见它睁开了眼睛。你惊醒时，枕头湿了一片。", "你把石头放回盒子，手是抖的。神父看了你一眼，什么也没说，只把盒子收走了。你走出地窖，阳光落在肩上，你站了很久，才觉得暖。"]}, "7": {"ritual": "让自己成为一束光", "ritualNote": "神话之境，是不再借圣堂的光——你自己，就是那束光。", "omens": ["你梦见自己站在圣堂中央，所有的烛火都熄了，只剩下你身上一层很淡的光。", "梦里的你没有惊讶，只是把光举高了一点，让亮处大了一圈。"], "success": ["你在圣堂里站了一夜，没有点灯。天亮时，神父推开门，看见你站在那里——你身上有一层很淡的光，不是烛火，不是圣水，是你自己的。", "他看了你很久，最后把那盏旧烛火端起来，吹灭了：'以后，圣堂有你就够了。'神话之境，成了。"], "fail": ["你在黑暗里站了一夜，身上没有亮起来。不是光不认你，是你还没把自己点透。", "神父推开门，看见黑暗里的你，什么也没说，只是把那盏烛火重新点着，放在你面前。你看着那盏火，知道它还在等你。"]}};
BREAKTHROUGH_V49.byJob["商人"] = {"guardian": {"tutor": {"name": "金秤家族执事", "bonus": 10, "rescue": 60, "desc": "在金秤家族管了三十年账的人。他说：'账房里的每一笔，都是一个人。'"}, "senior": {"name": "老行商", "bonus": 6, "rescue": 40, "desc": "跑遍大陆每条商路的人。他的驼队从没丢过货——他说不是运气，是规矩。"}, "friend": {"name": "合伙旧友", "bonus": 4, "rescue": 30, "desc": "跟你一起赔过钱，也一起赚过钱的人。他说：'账目要清，交情要厚。'"}}, "place": {"sacred": {"name": "金秤阁·账房", "bonus": 8, "crisis": -8, "desc": "金秤家族的账房。四面墙都是格子，每一格里都是一笔陈年旧账，锁着，不给人看。"}, "safe": {"name": "自家货栈", "bonus": 5, "crisis": 0, "desc": "堆满货物的旧货栈。空气里有麻袋和桐油的味道，是你发家的地方。"}, "wild": {"name": "商路驿站", "bonus": -5, "crisis": 10, "desc": "人来人往的驿站，消息多，眼也多。夜里冷，床板硬。"}}, "crises": [{"id": "merch_debt", "title": "旧账上门", "text": ["破境到一半，账房的灯忽然暗了。你听见算盘珠子的声音——很轻，很密，像有人在黑暗里拨着一笔陈年旧账。你认出了那笔账：你早年欠下的一笔，你以为已经平了，其实还差一个零头。"], "opts": [{"id": "a", "t": "把零头补上——哪怕亏本", "stat": "CHA", "pass": ["你打开钱匣，把那个零头数出来，放进账本的格子。算盘声停了。你合上账本，心里那根一直绷着的弦，松了。", "破境成了。执事后来查账，看见了那笔补上的零头，没有问，只把格子重新锁上。有些账，平了就是平了。"], "fail": ["你想补，却发现那个零头早就涨了——利滚利，比你以为的多得多。你握着钱袋，站在账房中央，第一次觉得算盘声压人。"]}, {"id": "b", "t": "不认——账已经清了", "stat": "CON", "pass": ["你把账本合上，说：'清了。'算盘声停了一瞬，又响起来，更密了。你听见黑暗里有人笑：'你说清，就清？'你握着账本，手心出汗，却一步不退。", "那声音见你不松口，渐渐远了。破境成了，可你知道，那笔账在你自己心里，还差一个零头。"], "fail": ["你不认账，算盘声却越来越响，响得你头皮发麻。你最终没能静下来，破境失败，坐在账房里，听着那声音响了一夜。"]}, {"id": "c", "t": "请执事来做中人", "stat": "CHA", "pass": ["你请执事来，让他在账本上做了个中人，把那个零头折成一笔新约。执事拨了拨算盘，说：'可以。'算盘声停了。", "你签下新约，把账本合上。破境成了——你欠的还在，但已经变成了一笔能还的债。"], "fail": ["执事来了，看了那笔账，摇了摇头：'这账，我作不了中。'你握着账本，第一次觉得，有些债，连中人都不敢沾。"]}]}, {"id": "merch_rival", "title": "对手压价", "text": ["破境到一半，货栈的门被敲响——是对头商行的人，趁着夜，来压你的价。他隔着门说：'你东城的货，我明天出三成价。你接不接？'"], "opts": [{"id": "a", "t": "不接——宁可压仓", "stat": "CON", "pass": ["你没有开门，隔着门板说：'不接。压仓就压仓。'门外的声音静了一会儿，又说：'你扛得住？'你说：'扛得住。'", "门外的人走了。你关紧门，继续破境。第二天，东城的货你压了仓，可你的信誉，没压。破境成了。"], "fail": ["你嘴上说不接，心里却算了半夜的账。天亮时你开了门，答应了三成价。门外的笑声传进来，你握着门闩，觉得那扇门，以后再难关紧。"]}, {"id": "b", "t": "开门谈——给他一个'接不了'的价", "stat": "CHA", "pass": ["你开了门，把对方让进来。你没有跟他谈三成，你给他算了一笔账：压价的成本、断货的损失、他自家商行的信用折损。你算得很慢，很细。", "他听完，沉默了很久，最后说：'行。我原价收。'他走后，你关上门，继续破境。这一夜，你睡得比谁都稳。"], "fail": ["你开门谈，他却不接你的账——他带来了更大的靠山。你谈崩了，货被压了价，破境也泡了汤。你坐在货堆中间，第一次觉得，账算得再清，也怕刀。"]}, {"id": "c", "t": "不接话——让执事去挡", "stat": "CHA", "pass": ["你让执事去应付。执事没有开门，隔着门板，跟他谈了一炷香。回来时，执事说：'谈好了，原价，明早交割。'", "你问怎么谈的。执事说：'我给他看了三本旧账。他回去算了算，不划算。'你听完，心里那口气顺了。破境成了。"], "fail": ["执事去挡，对方却不买执事的账——他只认你。你被逼着开了门，这一夜，生意没谈成，破境也黄了。"]}]}, {"id": "merch_abyss", "title": "深渊低语", "text": ["账房的灯在破境最深处暗了一下。你听见一个声音，像拨算盘那样拨着你的心：'你算了一辈子账，算没算过，你自己值多少？'"], "opts": [{"id": "a", "t": "拨一次自己的算盘——把答案算出来", "stat": "INT", "pass": ["你坐到账台前，把自己的'账'从头拨了一遍——不是钱，是那些你没做的事、没走的路。算到最后一颗珠子，你停住了：你值多少，取决于你还没做完的事。", "那声音没有答话。你合上算盘，继续破境，心里那笔账，比刚才清楚了很多。"], "fail": ["你拨到一半，算不下去了。你的账比你想的乱——不是数字乱，是有些事，你没敢记上去。你握着算盘珠，坐在账台前，坐到天亮。"]}, {"id": "b", "t": "回它——'我自己说了算'", "stat": "SPR", "pass": ["你说：'我自己说了算。'那声音静了很久，像从没见过这么不讲理的账房先生。最后它说：'有意思。'退了。", "你坐在账房中央，第一次觉得，有些账，不归算盘管。"], "fail": ["你说'我自己说了算'，那声音却笑了：'你说了算？那你为什么还在听我说话？'你答不上来。"]}, {"id": "c", "t": "让执事拨三遍算盘", "stat": "CHA", "pass": ["你请执事拨了三遍算盘。第一遍，算的是你的身家；第二遍，算的是你的信誉；第三遍，执事停下来，说：'第三遍，算的是你的良心——这个，我自己拨不了。'", "你听完，坐回账台前，把那第三遍，自己拨了。那声音没有再说话。破境成了。"], "fail": ["执事拨了三遍，第三遍也拨不下去。他合上算盘，说：'这账，我拨不了。'你握着算盘，第一次觉得，有些数字，比深渊还深。"]}]}], "1": {"ritual": "做第一笔不亏本的买卖", "ritualNote": "小贩凝元，是从'卖出去'到'卖对价'的那一步。", "omens": ["你最近摆摊，开始留意客人的眼睛——他问价之前，先看哪里，摸哪里，你都知道他心里的价。", "老行商路过你的摊子，站了一会儿，说：'你开始看人了。'"], "success": ["你做成了一笔买卖，价开得不高不低，客人没有还价。他走的时候，你看见他腰间的钱袋，还鼓着——你开对了价。", "你收摊时，数了数铜板，比昨天多了三枚。不多，但你知道，你开始'会卖'了。凝元，成了。"], "fail": ["你开价开高了，客人摇头走了。你追着降价，他更不买了。你守着摊子坐到天黑，一枚铜板也没进。", "老行商路过，说：'价开高了，是贪；追着降，是急。两个都占，客人不信你。'你把摊子收了，把他这句话记下了。"]}, "2": {"ritual": "替人保管一笔钱，分文不动", "ritualNote": "化意之境，是学会'信任'这笔账——别人信你，你守得住。", "omens": ["一个老农妇把攒了半辈子的钱交给你保管，说：'村里人都说你这人实诚。'钱袋很旧，扎口系的是一根红绳。", "你接过钱袋，觉得它比任何货款都重。"], "success": ["你把钱袋锁进最稳妥的柜子，一天看三遍。三个月后，老农妇来取，你原样还给她，红绳都没动过。她数了数，分文不差，朝你笑了笑。", "她走的时候，你站在柜台后，觉得那三个月的提心吊胆，值了。化意，成了。"], "fail": ["钱袋在你手里放了三天，你动了三次念头。第三次，你打开看了一眼，又赶紧合上。", "老农妇来取钱那天，你发现钱袋的封口被你动过——虽然分文未少，你心里却虚了一整晚。你没能晋，因为你没守住'不动'。"]}, "3": {"ritual": "谈成一笔让双方都满意的买卖", "ritualNote": "宗师之境，不是赚最多，是谈得'两边都顺'。", "omens": ["一笔大买卖找上你，对方是个老滑头。他开价很精，压得很死。", "你研究了他的账三天，发现他压你的价，是为了补他自家亏的窟窿——你知道了他的底牌。"], "success": ["你跟他谈了三个时辰。你没有压他的底牌，而是给他指了一条更省的路。他最终按你的价收了货，走的时候说：'你这人，做生意不狠。'你笑了笑：'狠不是本事，久才是。'", "他走后，你数了数这笔买卖的账，赚得不多，但你多了一个老客户。宗师之境，成了。"], "fail": ["你压了他的底牌，逼着他按你的价成交。他签了约，脸色很难看。", "三个月后，他再也没来过。你握着那份合约，忽然明白：你赢了这一笔，输了一条路。"]}, "4": {"ritual": "救活一笔快死的买卖", "ritualNote": "大宗师之境，是把'救不活的账'救活——不是靠钱，是靠脑子。", "omens": ["你合伙的商行出了事——一批货被扣在关口，眼看要赔光。合伙人急得满嘴起泡，找你拿主意。", "你连夜去关口看了一圈，心里有了一个数。"], "success": ["你找到扣货的官员，没有递钱，只递了一本账——账上算的是：这批货放行，关口三个月能多收多少税。官员看了半夜，第二天，货放了。", "货到手的当天，你把它转了个高价。合伙人分账时，多给你分了一成，你没有推。大宗师之境，在你把死账盘活的时候，成了。"], "fail": ["你算好了账，官员却不看。你等了三天，货被充公。你站在关口外，第一次知道：有些账，算得再清，也抵不过不讲理。", "你回去赔了合伙人一半的钱，自己吃了另一半亏。你坐在货栈里，看着空了的货架，坐到半夜。"]}, "5": {"ritual": "做一笔不求回报的买卖", "ritualNote": "传奇之境，是学会'赔'——不是不会算，是有时候，值得赔。", "omens": ["一个逃难的人带着一箱旧物找你，说想换几天的口粮。箱子里的东西不值几个钱，可他眼睛里的东西，你认得——是走投无路。", "你看了看那箱旧物，又看了看他。"], "success": ["你按市价买下那箱旧物，多给了他一袋口粮。他千恩万谢地走了。你把那箱旧物收进货栈，没有翻，也没有卖——你知道它不值钱，但有些买卖，算的不是钱。", "三个月后，那人的家人从外地赶来，找到你，说想赎回那箱旧物——那是他家的传家之物。你把箱子原样还给他们，没有收钱。传奇之境，在你学会'赔'的时候，成了。"], "fail": ["你按市价买下旧物，还了价，少给了半袋口粮。他走了，你看着那箱旧物，心里却一直过不去。", "你把它翻出来看了一遍，发现里面有一封信，写着他家的地址。你把信放回去，忽然觉得，自己那半袋口粮，本不该省的。"]}, "6": {"ritual": "把一笔旧债，一笔勾销", "ritualNote": "半神之境，是学会'免'——把该收的账，从账本上划掉。", "omens": ["你翻旧账，翻到一笔二十年前的债——欠债的人，早就不在了。债主的名字你也认得，是你年少时的恩人。", "你握着那页账，坐了很久。"], "success": ["你把那页账撕下来，放进炉火里。灰烬落在账台上，你看着它，觉得那笔债，烧得值。", "你合上账本，没有跟任何人说起。半神之境，在你学会'免'的时候，成了。你忽然明白，账房最大的本事，不是收，是放。"], "fail": ["你握着那页账，撕不下来。你把它放回账本，合上，又打开，合上，又打开。", "最后你还是把它留在了账本里。你坐在账房中央，看着那本旧账，第一次觉得，有些格子，锁得太久了。"]}, "7": {"ritual": "让自己的名字成为一张通行证", "ritualNote": "神话之境，是让'你的名字'本身，比任何货都值钱。", "omens": ["你梦见自己走在一条很长的商路上，路上每个驿站的人都认识你。他们不叫你的名字，只是点头，像你是一个不需要名字的人。", "你醒来时，天还没亮。你坐在账房中央，忽然想明白了一件事。"], "success": ["你签下了一份合约，没有带钱，没有带保人，只签了你的名字。对方看了你的名字，没有验货，没有验资，直接盖了章。", "你把合约收好，走出账房，阳光落在你肩上。你忽然知道，自己这辈子的账，算是做到头了——从今往后，你的名字，就是账本。神话之境，成了。"], "fail": ["你签了名，对方却坚持要验资。你把钱箱搬来，他数了三遍，才盖上章。", "你走出账房，觉得那三遍数钱声，像三记耳光。你坐在货栈里，第一次知道：你的名字，还差一截。"]}};

BREAKTHROUGH_V49.byJob["战士"] = {"guardian": {"tutor": {"name": "铁壁武道院教习", "bonus": 10, "rescue": 60, "desc": "在武道院教了三十年拳脚的老教习。他从不夸人，但会把你的名字记在小本上。"}, "senior": {"name": "老兵师兄", "bonus": 6, "rescue": 40, "desc": "从北方前线退下来的老兵，身上有三道疤，从不肯说哪道最疼。"}, "friend": {"name": "练武的挚友", "bonus": 4, "rescue": 30, "desc": "每天陪你过三百招的人。他说：'打不过你，也得让你打痛快。'"}}, "place": {"sacred": {"name": "铁壁武道院演武场", "bonus": 8, "crisis": -8, "desc": "青石地面被几代人的脚步磨得发亮。中央立着一面旧战旗，旗角缺了一角。"}, "safe": {"name": "武道院柴房", "bonus": 5, "crisis": 0, "desc": "堆满劈好的木柴，空气里有松木和汗味。安静，没人来。"}, "wild": {"name": "北城墙根", "bonus": -5, "crisis": 10, "desc": "风吹得紧，墙根的土又干又硬。离前线近，杀气重。"}}, "crises": [{"id": "war_blood", "title": "血气反冲", "text": ["破境到一半，你体内积攒的斗气忽然乱了——像一匹被缰绳勒急了的马，原地打转，蹄子刨得你五脏生疼。血从你鼻子里渗出来，你尝到一股铁锈味。"], "opts": [{"id": "a", "t": "压——用呼吸把它驯住", "stat": "CON", "pass": ["你闭上眼，把呼吸放长，一寸一寸地勒住那匹'马'。它挣了三次，第四次，终于顺着你的呼吸走了。你睁开眼，鼻孔里还挂着血，但你知道，这一关过了。"], "fail": ["你压得太急，血气反而冲上头顶。你眼前一黑，整个人向后栽倒，后脑勺磕在青石地上。护法把你扶起来时，你满嘴是血。"]}, {"id": "b", "t": "放——让它跑，跑完了再收", "stat": "STR", "pass": ["你索性不压了，站起身，在演武场里打了一趟拳。血气顺着拳路泄出去，一拳比一拳沉。最后一拳砸在石锁上，石锁裂了一道缝。", "你收拳站定，血气已经服了。你低头看拳面，破了一层皮，但心里那口气，顺了。"], "fail": ["你放得太开，血气成了野马。你收不住，一拳砸在墙上，墙没事，你的指节肿成了馒头。血气还在乱窜，你只能中断破境。"]}, {"id": "c", "t": "请护法搭把手——按住你的肩", "stat": "CHA", "pass": ["护法的手按在你肩上，一股沉稳的力道传下来。他什么都没说，只是按着。血气在他手下慢慢平了，像被一盆冷水镇住的火。", "他收回手时，肩头留了一个掌印，青紫的。你没有谢，他也没有等谢。老兵的默契，不用开口。"], "fail": ["护法按住了你的肩，却没能按住你的心。你心里那口气还在翻，斗气一波一波地顶上来，最后把护法也震开了半步。"]}]}, {"id": "war_enemy", "title": "仇人上门", "text": ["破境的消息不知道怎么就传了出去。半夜，演武场的门被一脚踹开——是你早年结下的对头，提着刀，堵在门口，身后还跟着两个帮手。"], "opts": [{"id": "a", "t": "起身迎战——破境可以等，脊梁不能弯", "stat": "STR", "pass": ["你从蒲团上站起来，斗气还没完全理顺，但你站得很直。你看着他，说：'等我半天。'他愣了一下。你擦了把脸上的血，把刀抄起来。", "那一仗打了很久，你赢了。赢得很狼狈，但你站着。境界虽然没成，可你心里那口气，比破境前更足。"], "fail": ["你带伤迎战，斗气不稳，三招就被他掀翻在地。护法冲上来架住他的刀，你才没被补上第二刀。你躺在青石地上，看着屋顶，忽然觉得很累。"]}, {"id": "b", "t": "让护法挡着，你继续破境", "stat": "CHA", "pass": ["护法横刀挡在门口，一句话没说。你闭上眼，继续破境。刀兵声在你身后响了很久，你一次也没有回头。", "等你睁开眼时，门口只剩护法一个人。他刀上豁了口，肩膀在渗血，看见你醒了，咧嘴一笑：'成了？'你点头。他把刀往地上一杵：'值了。'"], "fail": ["你让护法挡着，自己却静不下来。门外的刀兵声一声一声砸在你心里，你坐不住，最后冲了出去。两人一起受伤，境界也没成。"]}, {"id": "c", "t": "以退为进——先退，择日再战", "stat": "AGI", "pass": ["你收刀，看了他一眼：'今日不便，改日，你来找我。'他哼了一声，带着人走了。你关上门，把血擦干净，继续破境。", "心里那口气没散，但你知道，它会在改日，一起还。境界，成了。"], "fail": ["你退了一步，他当你是怕了，追进来补了一刀。你肩上挨了一记，破境彻底泡汤。你捂着伤口退到墙根，护法这才赶上来。"]}]}, {"id": "war_heart", "title": "心魔·怯", "text": ["破境最深处，你忽然看见自己站在一面战旗下——旗子缺了一角，正是演武场那面。可这一次，旗子倒了。你听见自己在问：'要是当年那一战，你输了，你还会是现在的你吗？'"], "opts": [{"id": "a", "t": "扶起旗子——'输了也是我'", "stat": "SPR", "pass": ["你走过去，把那面旗子扶起来。它在你手里沉甸甸的，像扛着一个没说出口的答案。你说：'输了也是我。'旗子没有倒。", "你睁开眼，演武场里的风正好从旗角吹过。你低头看自己的手，稳的。"], "fail": ["你伸出手，又缩回来。那面旗子在你眼前倒下去，你没能扶住。你站在那儿，听见自己说：'要是……'——就这一句，破境断了。"]}, {"id": "b", "t": "对着旗子打一套拳", "stat": "STR", "pass": ["你没有去扶，而是对着倒下的旗子，打了一整套拳。拳拳带风，拳拳砸在空气里。打到最后一拳，旗子自己立了起来——是被你的拳风带起来的。", "你收拳。风把旗角吹得猎猎响。你心里那个问题，已经不用回答了。"], "fail": ["你打得太急，拳头砸在旗杆上，旗杆没断，你的指节先裂了。你蹲在地上，看着那面旗，第一次觉得它压得人喘不过气。"]}, {"id": "c", "t": "问护法——你怕过吗", "stat": "CHA", "pass": ["你睁开眼，看向护法。他想了想，把袖子撩起来，露出那道最深的疤：'怕过。怕得整夜睡不着。'他顿了顿：'怕完，还得上。'", "你听完，点了点头，重新闭上眼。这一次，你心里那根弦，松了半格。"], "fail": ["你问出口的时候，心里已经怯了。护法没有回答你——他看出来了。你坐在那儿，觉得那面旗子，越看越重。"]}]}], "1": {"ritual": "让第一缕斗气听话", "ritualNote": "壮丁凝元，是把丹田里那股躁动的力量，从'野马'驯成'战马'。", "omens": ["你最近劈柴，柴刀落下去，木柴会先颤一下才裂开——以前不是这样的。你试着攥了攥拳，拳头里像多了一股使不完的劲。", "老教习看了你一眼，扔过来一块青石：'捏碎它。'你捏了三下，青石裂了。他点点头，没说话。"], "success": ["你盘坐在演武场中央，把那股劲引着走完一圈经脉。它走第一遍时横冲直撞，走第二遍时开始跟着你的呼吸，第三遍，它在你丹田里落了下来，像一匹马终于认了鞍。", "你睁开眼，把刚才那块青石捡起来，虚虚一握——碎成了粉。凝元，成了。"], "fail": ["那股劲不受你管，在你经脉里横冲直撞，撞得你手脚发麻。你强压了一夜，最后吐出一口血，才把它压回去。", "老教习递过来一块帕子：'驯马，先得让它跑累。你急什么。'"]}, "2": {"ritual": "接住教习的全力一拳", "ritualNote": "化意之境，是身体先学会'挡'——不是用招，是用意。", "omens": ["你最近总觉得老教习的拳变慢了。不是他慢了，是你快了。他出拳时，你能看见他肩头先沉一下——那是他要发力的地方。", "老教习也发现了。他看了你一眼，把围裙摘了：'明天，接我全力一拳。'"], "success": ["你站在演武场中央，老教习的拳砸过来时，你没有躲，没有挡——你顺着他的拳路，整个人偏了半寸。拳风擦着你的脸过去，带起一缕头发。", "你站在原地，一步没退。老教习收拳，看着你，慢慢点了点头：'行了。你懂'意'了。'化意，成了。"], "fail": ["你接住了那拳，硬接的。拳风砸在你胸口，你退了三步，胸口闷得说不出话。老教习收了拳：'硬接是本事，可你还没到那个份上。'", "你咳了半天，觉得胸口那块淤青，比什么都重。"]}, "3": {"ritual": "背对旗子，听风辨敌", "ritualNote": "宗师之境，是眼睛可以休息了——身体的'听'比眼睛更快。", "omens": ["你最近闭眼比睁眼多。夜里走在巷子里，你闭着眼也能知道前面三步有个水坑，左拐的墙根有人蹲着抽烟。", "你把这个跟老教习说了。他沉默了一会儿：'那明天，你背对着我。'"], "success": ["你背对老教习站着，他说'来'。你凭风里的声响，侧身让过第一拳，抬手架住第二下，第三下，你反手扣住了他的手腕。", "他愣了很久，然后笑了：'成。宗师了。'你睁开眼，演武场的风正好吹过旗角——那面缺角的战旗，在你背后猎猎地响。"], "fail": ["你背对着他，第一拳就挨实了。你被砸得前扑一步，转过身来，老教习看着你：'风是听见了，可你信不过自己。'", "你重新闭上眼，练到天黑。每一次，你都比他慢半拍。"]}, "4": {"ritual": "独自守一夜城门", "ritualNote": "大宗师之境，不是打赢，是守住——守一整夜，一步不退。", "omens": ["北境的信在傍晚送到，说前线吃紧，城里的守军调走了一半。城防官找到你，欲言又止。", "你接过他手里的长枪，说：'我去。'他愣了一下，没有推辞，只说了句：'后半夜冷。'"], "success": ["你站在城门口，从日落到天明。夜里的风灌进衣领，你一步没有退。远处有过几回可疑的动静，你握紧长枪，它们退了。", "天亮时，城防官来接你的班。他看见你脚边磨出的两道沟，又看了看你手里的枪，没说话，只是拍了拍你的肩。大宗师，成了——没有敌人，没有血，只是守住了。"], "fail": ["后半夜，真的来了动静。你握枪迎上去，可那动静只是几只野狗，抢食抢到了城根。你松了口气，退回来时，发现自己在抖。", "你守到天明，一步没退，可你知道，你的心退过半步。这一境，还没成。"]}, "5": {"ritual": "在战场遗迹里听一次旧风", "ritualNote": "传奇之境，是去听那些没能活着回来的人，最后想说的话。", "omens": ["你去了北境的旧战场。风刮过荒草，草茎弯下去，又弹起来。你蹲下来，捡起半截锈断的枪头，枪头上还缠着一缕早就褪色的布。", "你握着那截枪头，忽然听见风里有很多声音——很轻，很乱，像一场没能说完的话。"], "success": ["你在旧战场上坐了一夜。风里那些声音，你听懂了六七成：有人喊'跟上'，有人喊'别管我'，有人的声音戛然而止。你没有害怕，只是坐着，替他们听完。", "天亮时，你把那截枪头重新立起来，插在草地里。风从枪头上吹过，声音比昨夜安静了许多。传奇之境，在那阵风里，成了。"], "fail": ["你在旧战场上坐了一夜，什么也没听见。风只是风，草只是草，那半截枪头只是一块锈铁。", "你握着它，觉得自己像个闯进别人葬礼的陌生人。你把它放回原处，转身走了。回程的路上，你一直在想：是不是你心里那扇门，还没打开。"]}, "6": {"ritual": "替一面倒下的旗子，站一回岗", "ritualNote": "半神之境，是扛起一面没人扛得动的旗——不为别人，为自己。", "omens": ["你在旧战场深处发现一面倒下的旗。旗杆断了，旗面烂了大半，只剩一角还看得出颜色——是你没见过的颜色。", "你蹲下来看它，觉得它好像认识你。你伸手去扶，旗杆在你手里断得更碎。"], "success": ["你找了根新的杆子，把那面旧旗重新立起来。旗面太烂了，风一吹就散，可你站着，替它守了一天一夜。", "第二天清晨，你听见风里传来一声很轻的'谢了'——像那面旗，又像别的什么。你离开时没有回头。半神之境，在你替它站完那班岗的时候，成了。"], "fail": ["你把旗立起来了，可风一吹，它就散了。你蹲在散落的布片中间，捡了又捡，怎么也拼不回原样。", "你蹲到天黑，最后把那些布片收进怀里，带回城里。你知道有些东西，扶起来是一回事，立得住是另一回事。"]}, "7": {"ritual": "与自己的战旗合一", "ritualNote": "神话之境，是把自己锻成一面旗——从此你站在那里，就是万军的方向。", "omens": ["你梦见自己站在演武场中央，那面缺角的战旗飘在你头顶。风很大，旗角猎猎地响，像在跟你说话。", "你伸手去接旗，旗杆落进你手里，滚烫——像握着一柄刚出炉的刀。"], "success": ["你握着那面旗，从日落到日出，一步未动。风把你的衣角吹成旗角，把你的影子吹成一面旗的影子。", "天亮时，你睁开眼，手里的旗已经不见了——它在你背上，像一层洗不掉的颜色。你站起身，演武场的风从你身后吹过，整条街都安静了一瞬。神话之境，成了。"], "fail": ["你握着旗，站了一夜，天明时它还在你手里，沉甸甸的，不肯融进你身体。你松开手，它落回旗座。", "你知道，旗还不认你。不是它不愿，是你还没到那个'立得住'的份上。你把它放好，转身离开，像从前每一次那样。"]}};
BREAKTHROUGH_V49.byJob["骑士"] = {"guardian": {"tutor": {"name": "护教骑士长", "bonus": 10, "rescue": 60, "desc": "在圣堂守了半辈子的老骑士。他的剑鞘比他的剑更旧，他说那是有道理的。"}, "senior": {"name": "巡游骑士前辈", "bonus": 6, "rescue": 40, "desc": "走过大陆每一座城的骑士。他话不多，但他讲过的每一座城，你都没忘。"}, "friend": {"name": "誓约同行者", "bonus": 4, "rescue": 30, "desc": "不是骑士，但信你。他说：'你立的誓，我替你记着。'"}}, "place": {"sacred": {"name": "圣堂·誓言厅", "bonus": 8, "crisis": -8, "desc": "穹顶很高，阳光从彩窗漏下来，把地面染成七种颜色。历代骑士的誓词刻在石柱上。"}, "safe": {"name": "圣堂侧室", "bonus": 5, "crisis": 0, "desc": "给守夜人歇脚的小间。木床很硬，被褥有圣水的味道。"}, "wild": {"name": "城外古道", "bonus": -5, "crisis": 10, "desc": "风大，尘多，常有赶路的人。骑士该去的地方，本来就不是圣堂。"}}, "crises": [{"id": "knight_oath", "title": "誓约动摇", "text": ["破境至深处，你忽然听见自己当年立誓时的声音——很年轻，很响。可紧接着，另一个声音问你：'这些年，你守的誓约，真的都对吗？'你答不上来。"], "opts": [{"id": "a", "t": "重立誓约——'我守的，是我信的'", "stat": "SPR", "pass": ["你在心里把那句誓约重新念了一遍，念到一半，改了一个字。改完之后，你心里那根弦没有断，反而更稳了。", "护教骑士长后来听说你改了誓词，看了你很久，说：'誓约不是刻死的，是会长的。你懂这个，就比我们那代人强。'"], "fail": ["你想重立，却发现自己连原来的那句都念不全了。你站在誓言厅里，听着自己的声音在穹顶下散掉，第一次觉得，誓言这么轻。"]}, {"id": "b", "t": "守旧誓——一个字不改", "stat": "CON", "pass": ["你把原来的誓约一字一字念完，念到最后，声音哑了。可你心里清楚，你信它。信的东西，不用改。", "破境成了。护教骑士长看着你，什么也没说，只是在你肩上按了一下——那一下，很重。"], "fail": ["你把旧誓念了三遍，越念越虚。你知道自己在骗自己——有些字，你已经不信了。你强撑着念完，破境却怎么也推不动。"]}, {"id": "c", "t": "问护法——他当年怎么守住的", "stat": "CHA", "pass": ["你睁开眼，问护法。他想了想，说：'我不是守住了，我是每天都重新选一遍。'他顿了顿：'选到今天，还没选错。'", "你听完，闭上眼，重新选了一遍。这一次，你选得比第一次还稳。"], "fail": ["护法答不上来。他坐在你对面，沉默了很久，最后说：'实话说，我也有过想放下剑的时候。'你听完，心里更乱了。"]}]}, {"id": "knight_abyss", "title": "深渊低语", "text": ["誓言厅的烛火忽然暗了一下。你听见一个声音，很轻，很熟——像你心里某个一直没敢听的部分在说话：'你守的圣光，照不亮的地方，我来替你照。'"], "opts": [{"id": "a", "t": "点亮烛火——'我的路，我自己照'", "stat": "SPR", "pass": ["你伸手，把暗下去的烛火重新点亮。火苗跳了跳，在你手边稳住了。那声音没有再说第二遍——它知道，这盏灯，你点定了。", "烛火在你手里亮了一整夜。你数了数，一共亮了八次——每一次，都是你心里的一关。"], "fail": ["你伸手点烛，火苗却在你指尖躲开。你点了三次，它暗了三次。那声音在你身后，低低地笑了一声。"]}, {"id": "b", "t": "把剑横在膝上——'我听过更会说的'", "stat": "CON", "pass": ["你把剑横在膝上，剑鞘上的旧痕对着烛火。你说：'我听过更会说的。'那声音顿了顿，像在辨认什么，然后退了。", "有些话，剑比你更早听过。它替你记住了。"], "fail": ["你把剑横在膝上，那声音却绕过了剑，贴着你的耳根说：'剑能护你，能护你的心吗？'你握着剑柄，手心全是汗。"]}, {"id": "c", "t": "请护法诵一段圣言", "stat": "CHA", "pass": ["护法在门外诵了一段圣言。声音不高，但很稳，像一堵看不见的墙。那声音听了半句，就静了。", "圣言停了，烛火还亮着。你听见护法在门外说：'好了，继续。'你点了点头，重新闭上眼。"], "fail": ["护法诵了圣言，那声音却笑了：'借来的墙，挡不住借来的火。'你心里一沉——它说得对。你借来的东西，确实不够稳。"]}]}, {"id": "knight_rival", "title": "旧敌相寻", "text": ["破境的消息传到城外。半夜，有人叩响圣堂的门——是你的旧敌。他隔着门说：'你立誓守护的人里，没有你欠过我的一条命吗？'"], "opts": [{"id": "a", "t": "开门，把话说清", "stat": "CHA", "pass": ["你打开门，站在门里，没有让开。你看着他，说：'欠的，我还。但我还之前，你让不让路，是你的事。'他沉默了很久，退了一步：'你变了很多。'", "他走了。你关上门，回到誓言厅，继续破境。门外的月光照进来，你心里，比月光还亮。"], "fail": ["你开了门，他却不是来谈的。他带着人来，你被迫中断破境，在圣堂门口打了一架。你赢了，可誓约厅的烛火，被你自己的血溅灭了两盏。"]}, {"id": "b", "t": "不开门——'今日我在破境'", "stat": "CON", "pass": ["你没有开门，隔着门板说：'今日我在破境。你的事，改日。'门外的声音静了很久，最后说：'好，我等你。'", "你听着他的脚步声走远，重新坐下。那一声'我等你'，没有让你分心，反而让你更稳了——有些债，该还的，逃不掉，也压不垮。"], "fail": ["你不开门，他在门外骂了半夜。你听着那些话，一个字也静不下去。天亮时你推开门，他已经走了，你的破境也黄了。"]}, {"id": "c", "t": "请护法去传一句话", "stat": "CHA", "pass": ["护法替你出门，传了一句话：'他记着。改日，我替他还。'门外的旧敌听了，哼了一声，走了。", "护法回来时，肩上多了一道白霜。他掸了掸，说：'外头冷。你里面，暖着就行。'你闭上眼，觉得心里确实暖。"], "fail": ["护法替你传话，旧敌却不肯认护法的账。他堵在门外不走，你只好自己出去。这一夜，谁也没睡成。"]}]}], "1": {"ritual": "立下第一句誓约", "ritualNote": "见习骑士凝元，是从'想要守护'到'决定守护'的那一步。", "omens": ["你最近路过圣堂时，总会在门口站一会儿。不是想进去，是听见自己心里有个声音在说：'要是那时候……'——你没让它说完。", "护教骑士长有一天叫住你，问：'你站门口，是等什么？'你答不上来。他看着你，说：'想好了再进来。'"], "success": ["你走进誓言厅，在石柱前站定。你念出那句在心里念了很久的誓约，声音不高，但很稳。穹顶把声音折回来，像有人在替你重复一遍。", "你走出圣堂时，觉得肩上多了一点重量——不多，但你第一次觉得，'守护'这两个字，真的落在你身上了。凝元，成了。"], "fail": ["你站在石柱前，那句誓约却怎么也说不出口。你张了张嘴，又合上。护教骑士长没有催你，只是说：'说不出口的誓，比说出口的更重。你还没准备好。'", "你走出圣堂，门口的台阶，比进来时长了。"]}, "2": {"ritual": "替一个人挡一次风雨", "ritualNote": "化意之境，是第一次真正'挡'在别人前面——不是表演，是本能。", "omens": ["雨天，你在城门口看见一个老人摔在泥地里，半天爬不起来。你几乎是本能地冲过去，替他挡着雨，把他扶起来。", "老人道谢时，你忽然发现自己没有想过'该不该'——你已经做了。"], "success": ["你站在老人面前，替他挡了那阵雨。雨打在你背上，你一动没动。老人回家后，你站在雨里，觉得背上那层凉意，比圣堂的圣水还让人踏实。", "化意，成了。你终于知道，'守护'不是学来的，是挡出来的。"], "fail": ["你冲过去时慢了一步，老人已经摔得满脸泥。你扶起他，他道谢，你心里却一直过不去。", "你回到圣堂，跪在誓言厅里，把那天的雨，反复想了一夜。护教骑士长路过，只说了一句：'慢一步，比不伸手好。'"]}, "3": {"ritual": "守一夜圣堂的烛火", "ritualNote": "宗师之境，是学会守'看不见的东西'——比如烛火，比如誓言。", "omens": ["护教骑士长把守夜的任务交给你，只交代了一句：'烛火不能灭。'", "那夜风很大，圣堂的门缝里漏进来的风，把烛火吹得东倒西歪。你伸手护着，风却从指缝里钻。"], "success": ["你守了一夜，烛火灭过三次，你点了三次。最后一次，风忽然停了——不是风停了，是你找到用身体挡风的角度。", "天亮时，护教骑士长推开门，看见你还保持着那个姿势。他没有说话，只是把那盏烛火端起来，看了一会儿。宗师之境，在你把'守'字练进骨头里的时候，成了。"], "fail": ["风太大，烛火灭了五次。你最后一次点着它时，手已经抖得握不住火石。", "护教骑士长进来，看见一屋子的蜡油和灰烬。他没有责备，只说：'烛火会灭，人得学会在它灭之前，找到自己的光。'"]}, "4": {"ritual": "护送一队陌生人穿过险地", "ritualNote": "大宗师之境，是守护从'你认识的'变成'你路过的'——只要是该守的，都守。", "omens": ["商队找上你，说要穿过北边那段常有盗匪的山路。他们出价不高，但领队的人说：'听说你立过誓。我们信誓约。'", "你看着那队人——有老人，有孩子，有赶着羊的牧民。你答应了，没有谈价钱。"], "success": ["山路走了一半，盗匪真的来了。你一个人站在路中央，剑出鞘，没有退。盗匪看了看你，又看了看你身后那队人，骂了一声，退了。", "你把商队送出山口，领队的人把一袋钱塞给你。你没有收，只把剑收回来：'顺路。'大宗师之境，在那条山路上，成了。"], "fail": ["山路走到一半，盗匪来了，比预想的多。你护住了老人孩子，却丢了商队的两匹驮马。", "你把商队送出山口，领队的人没说什么，但你看见他清点货物时，手停了一下。你回到圣堂，跪了很久。"]}, "5": {"ritual": "为一句无人听见的誓言站岗", "ritualNote": "传奇之境，是守一句没有人听见的誓言——只有你知道，可你守。", "omens": ["你在旧战场上遇见一个老兵，他临死前握住你的手，说了一句没人听见的话。他咽气后，你把他埋了，把那句话带走了。", "那句话很简单，可它太重了，重到你回到城里，还觉得它压在舌根。"], "success": ["你替他守了那句话。没有人为你立碑，没有人知道你守的是什么，可你守住了。", "三个月后的夜里，你梦见那个老兵，他朝你点了点头，然后走了。你醒来时，枕头湿了一角。传奇之境，在你守完那句无人听见的誓言时，成了。"], "fail": ["你把那句话忘了。不是故意的，是日子太忙，它在你心里慢慢褪了色。", "等你想起来的时候，已经想不起原话了。你跪在誓言厅里，觉得对不起那个老兵，也对不起自己。"]}, "6": {"ritual": "在圣光照不到的地方站一夜", "ritualNote": "半神之境，是去圣光照不到的暗处——看看那里的黑，然后决定还守不守。", "omens": ["护教骑士长带你去了一处地窖。地窖很黑，很冷，角落里有旧年的血迹。他说：'这里没有圣光。你站一夜，再决定你要不要继续守。'", "你站在黑暗里，听见自己的心跳。很响，像一面鼓。"], "success": ["你在黑暗里站了一夜。没有圣光，没有烛火，只有你自己。天亮时，你推开地窖的门走出来，护教骑士长还坐在门口，一夜没动。", "他问你：'还守吗？'你点了点头。他什么也没说，但你把地窖的门，从外面锁上了——不是锁住黑暗，是锁住自己回头的心。半神之境，成了。"], "fail": ["你在黑暗里站了不到半个时辰就出来了。不是怕黑，是你忽然不确定——你守的东西，在暗处还站不站得住。", "护教骑士长看着你，没有责备。他只是把那扇地窖的门，重新推开：'什么时候想清楚了，再进去。'"]}, "7": {"ritual": "让自己成为一盏灯", "ritualNote": "神话之境，是不再借圣堂的光——你自己就是那盏灯。", "omens": ["你梦见自己站在誓言厅里，手里的烛火越烧越亮，最后亮得盖过了穹顶所有的彩窗。", "梦里的你没有惊讶，只是把烛火举高了一点，让光落得更远。"], "success": ["你在誓言厅里站了一夜，没有点灯。天亮时，护教骑士长推开门，看见你站在那里——你身上有一层很淡的光，不是烛火，不是圣水，是你自己的。", "他看了你很久，最后把那盏旧烛火端起来，吹灭了：'以后，圣堂有你就够了。'神话之境，成了。"], "fail": ["你在黑暗里站了一夜，身上没有亮起来。不是光不认你，是你还没把自己点透。", "护教骑士长推开门，看见黑暗里的你，什么也没说，只是把那盏烛火重新点着，放在你面前。你看着那盏火，知道它还在等你。"]}};
BREAKTHROUGH_V49.byJob["游侠"] = {"guardian": {"tutor": {"name": "巡林者前辈", "bonus": 10, "rescue": 60, "desc": "在林子里住了三十年的人。他能从苔藓的长向说出哪边是北，从鸟叫听出几里外有人。"}, "senior": {"name": "猎户师兄", "bonus": 6, "rescue": 40, "desc": "打猎从不空手。他说：'猎物不是打来的，是林子愿意给的。'"}, "friend": {"name": "故交猎人", "bonus": 4, "rescue": 30, "desc": "小时候一起在林子里摸过鸟蛋的人。他不问你去哪，只问：'带够干粮没？'"}}, "place": {"sacred": {"name": "老橡树根", "bonus": 8, "crisis": -8, "desc": "林深处一棵几人合抱的老橡树，树根盘成一张天然的大椅。树皮上有历代巡林者刻下的记号。"}, "safe": {"name": "猎屋", "bonus": 5, "crisis": 0, "desc": "林边的小木屋，墙上有兽角和旧箭袋，炉膛里留着昨夜的灰。"}, "wild": {"name": "断崖风口", "bonus": -5, "crisis": 10, "desc": "风大得能吹跑帽子。视野开阔，也暴露。离最近的村子有半天路。"}}, "crises": [{"id": "ranger_storm", "title": "天变·骤雨", "text": ["破境到一半，天色忽然暗了。你听见林子里所有的鸟在同一瞬间噤声——那是风暴要来的前兆。你选的地方，挡不住这场雨。"], "opts": [{"id": "a", "t": "就地扎营——用树根和雨布撑住", "stat": "SURVIVE", "pass": ["你抢在雨落下来之前，用树根和雨布搭了一个能挡住风雨的窝。你缩在里面，听着雨砸在布上，一下一下，像鼓点。", "雨停时，你从窝里钻出来，浑身是泥，但境界稳住了。你摸了摸树根上的记号，觉得这棵树，算是认识你了。"], "fail": ["你搭得太急，雨布被风掀翻。你被雨淋了个透，破境也泡了汤。你浑身湿透地站在雨里，觉得自己像个笑话。"]}, {"id": "b", "t": "不躲——让雨浇", "stat": "CON", "pass": ["你索性不躲了，坐在树根下，让雨浇。雨打在肩上，打进衣领，你一动不动。你的呼吸比雨声更稳。", "雨停时，你睁开眼，浑身湿透，可你心里那团火，比雨前更旺。你站起来，甩了甩水，觉得这林子，今天对你很客气。"], "fail": ["雨太大，你被浇得发抖，最后发起烧来。护法把你拖回猎屋，你烧了三天，破境彻底黄了。"]}, {"id": "c", "t": "换地方——往林深处走", "stat": "AGI", "pass": ["你收拾东西，往林深处走。雨追着你下了半里，最后被林子挡在身后。你在另一棵老树下坐定，重新开始。", "这一夜，雨在林外下了个透。你在林子里，听着雨声，像听一首很远很远的歌。"], "fail": ["你往林深处走，却迷了路。雨在林子里变得更大，你找了半天才找到一个避雨的树洞。折腾了一夜，破境没成，你还丢了干粮。"]}]}, {"id": "ranger_poacher", "title": "盗猎者", "text": ["破境到一半，你听见林子里有不该有的声音——是陷阱夹子的脆响，还有动物受伤的哀鸣。有人在你守的林子里，下了夹子。"], "opts": [{"id": "a", "t": "中断破境，先救猎物", "stat": "CHA", "pass": ["你站起来，循着声音找过去，把夹子解开，把受伤的动物放走。你处理完回到树根下，重新坐下。", "破境虽然晚了一个时辰，却比你想象中更稳——你心里那口气，顺了。天亮时，你在夹子旁边留了一行字：'这林子，有主。'"], "fail": ["你救下了猎物，自己却被夹子伤了脚。你瘸着回到树根下，血把泥土染深了一块。破境没成，你靠在树根上，看着那行字，觉得刺眼。"]}, {"id": "b", "t": "守株待兔——等盗猎者来收夹子", "stat": "AGI", "pass": ["你在暗处蹲了一夜。天亮时，盗猎者来了。你从树影里走出来，他没有跑，也没有动手——他只是看着你，看了很久，然后弯腰，把夹子收走了。", "他走的时候，你在他背后说：'下不为例。'他没有回头。你回到树根下，觉得这一夜，比破境还值。"], "fail": ["你蹲了一夜，盗猎者没有来。天亮时你回到树根下，发现夹子还在，而你的破境，已经凉了。"]}, {"id": "c", "t": "换个方向——不跟他耗", "stat": "INT", "pass": ["你把夹子收走，埋了，在附近重新选了一棵安静的老树。你背对着那条小径，不再去听那些声音。", "这一夜很静。破境成了。你走的时候，在那棵老树根上，刻了一个小小的记号——是你自己的。"], "fail": ["你换了地方，却总想着那些夹子。你在新树根下坐了一夜，心里那只受伤的动物，一直没走。"]}]}, {"id": "ranger_abyss", "title": "深渊低语", "text": ["林子在破境最深处忽然静了。没有鸟叫，没有虫鸣，只有你耳根处一个声音，很轻：'你守的这片林子，迟早会老。你守得住吗？'"], "opts": [{"id": "a", "t": "摸一摸树皮——'它老了，我还守着'", "stat": "SPR", "pass": ["你伸手摸了摸老橡树的树皮，粗糙，温热。你说：'它老了，我还守着。'那声音没有答话——它大概没想到，你会这么答。", "林子慢慢恢复了声音。鸟叫回来，虫鸣回来，你坐在树根下，觉得自己也是这林子的一部分。"], "fail": ["你答不上来。林子会老，你会老，你守的东西，好像都在老。你坐在树根下，第一次觉得这林子这么大，你这么小。"]}, {"id": "b", "t": "反问——'你守过什么'", "stat": "INT", "pass": ["你问那声音：'你守过什么？'它沉默了很久，像从没想过这个问题。最后它说：'我什么都不守。'你说：'那就难怪你只能躲在暗处说话。'它退了。", "这一夜，林子格外安静。你坐在树根下，觉得自己比那声音，活得明白。"], "fail": ["你反问了，它却笑了：'我不守，所以我不会失去。你呢？'你答不上来，它在你耳边笑了很久才退。"]}, {"id": "c", "t": "吹响旧哨——用哨声压过它", "stat": "CHA", "pass": ["你摸出腰间的旧哨子，吹了一声。哨声在林子里传开，惊起几只鸟。那声音被哨声冲散，像雾见日头。", "哨子是你小时候的，哨口磨得发亮。你吹完，把它放回腰间，觉得它比圣堂的钟还管用。"], "fail": ["你吹响哨子，那声音却顺着哨声爬回来，缠着你不放。你吹了一夜，天快亮时它才退。你哑着嗓子，靠在树根上，一夜没合眼。"]}]}], "1": {"ritual": "独自在林子里过一夜", "ritualNote": "猎户凝元，是先学会不靠任何人，在林子里活过一夜。", "omens": ["你最近进林子，总觉得自己被什么东西跟着。你回头，什么也没有，可树影总是比你慢半拍。", "巡林者前辈递给你一包火石：'今晚，别回来。'"], "success": ["你在老橡树根下坐了一夜。夜里的林子很吵——虫鸣、兽叫、风声，你一件件认出来。天快亮时，一只鹿从你面前走过，看了你一眼，没有跑。", "它认得你不是威胁。你看着它走进晨雾里，觉得这林子，算是给你递了第一张名帖。凝元，成了。"], "fail": ["你怕了。半夜的风声把你吓得缩成一团，火石擦了三次都没点着。天没亮你就跑回了猎屋，巡林者前辈在门口，什么都没说，只把火石收回去了。"]}, "2": {"ritual": "读懂一枚脚印", "ritualNote": "化意之境，是从一枚脚印里，读出它主人的心事。", "omens": ["你在溪边发现一枚脚印，不是人的。你蹲下来看了很久，看出它受过伤——右前掌的着力点偏了。", "巡林者前辈走过来，看了一眼：'说说。'你说了。他点了点头，没评价对错。"], "success": ["你顺着那枚脚印，找到了那只受伤的兽。你远远看着它舔伤口，没有靠近。你记住了它的路线，记住了它觅食的规律。", "三天后，你在它常喝水的地方，放了一小块盐。它闻了闻，吃了。化意，成了——你第一次和一只兽，达成了'不打扰'的默契。"], "fail": ["你顺着脚印追过去，追得太急，把那只兽吓跑了。脚印也断了，你蹲在断掉的脚印前面，觉得它像一句没说完的话。", "巡林者前辈路过：'看脚印，不是追脚印。'你点了点头，把这句话记下了。"]}, "3": {"ritual": "听风辨位——闭眼射一箭", "ritualNote": "宗师之境，是眼睛可以休息了，风会告诉你方向。", "omens": ["你最近练箭，开始闭着眼。你听见风从东边来，吹动草尖，听见树梢的叶子在哪个方向响。", "巡林者前辈把一只旧箭囊递给你：'里面有一只箭，是歪的。你摸出来。'你闭着眼，摸了一遍，摸出来了。"], "success": ["你闭着眼，站在林子里。巡林者前辈把一只铜铃挂在远处的树枝上，风一吹就响。你说：'风会告诉我。'然后射出一箭。", "箭穿过铃声落下的方向，钉在树枝上——离铜铃三指。你睁开眼，前辈把那枚歪箭拿出来，给你看：'这一箭，不歪。'宗师，成了。"], "fail": ["你闭着眼射了三箭，全偏了。风骗了你，或者说是你还没学会听风。", "前辈把那只歪箭放回箭囊：'风不是骗你，是你还没把自己放空。'你把箭囊背好，往林子里走去。"]}, "4": {"ritual": "把一只兽送回家", "ritualNote": "大宗师之境，不是猎杀，是送归——把受伤的兽，送回它该回的地方。", "omens": ["你在陷阱边发现一只受伤的幼兽，后腿被夹伤，血淋淋的。它看见你，缩成一团，眼睛却盯着你，不眨。", "你蹲下来，把手里的干粮掰了一半，放在它面前。它没吃，但也不跑了。"], "success": ["你花了七天，把它的伤养好。第七天，你把它带到林子深处，松开手。它走了两步，回头看你一眼，然后走进林子里，没有回头。", "你在原地站了很久，觉得心里空了一块，又填满了什么。大宗师之境，在你学会'送归'的时候，成了。"], "fail": ["你养了它七天，它伤好了，却不肯走。它跟着你回了猎屋，睡在你脚边。你试着把它送回去三次，它三次都跑回来。", "你蹲在猎屋门口，看着它，第一次觉得'野'这个东西，不是教得会的。你把门敞着，一夜没关。"]}, "5": {"ritual": "替一片枯死的林子守灵", "ritualNote": "传奇之境，是去守一片已经没有生命的地方——守的不是树，是记忆。", "omens": ["山火过后，你去了那片焦黑的林子。树是黑的，地是黑的，风一吹，灰扬起来，呛得人睁不开眼。", "巡林者前辈没有来。他托人带了一句话：'去看看，然后回来。'"], "success": ["你在焦林里坐了三天。第三天夜里，你在灰堆里看见一点绿——是一株新芽，从焦土里钻出来。你蹲下来，替它挡着风，守了它一夜。", "天亮时，你把周围那圈焦土拢了拢，给那株芽让出一点地方。你走的时候，它在风里摇了一下，像在跟你道别。传奇之境，成了。"], "fail": ["你在焦林里坐了三天，什么也没看见。灰还是灰，黑还是黑，风一吹，什么也不长。", "你回到猎屋，把这件事跟前辈说了。他沉默了很久：'有些林子，要等很多年。你去的，不是时候。'你点了点头，心里那点绿，还没发出来。"]}, "6": {"ritual": "与老橡树道别", "ritualNote": "半神之境，是学会跟'守了一辈子'的东西道别——不是离开，是把位置让出来。", "omens": ["你最近发现老橡树的根，有一段枯了。你蹲下来看，看了一下午。它老了，你也知道，它一直在老。", "巡林者前辈来了一趟，站在树前，看了很久，说：'它快到时候了。你也是。'"], "success": ["你在老橡树根下坐了一夜，像第一次进林子那样。天亮时，你把树根上自己的记号擦了，重新刻了一个新的——不是巡林者的记号，是你自己的。", "你站起来，朝老橡树点了点头，转身走出林子。你没有回头，因为你听见身后的风里，传来一声极轻的'嗯'。半神之境，成了。"], "fail": ["你不肯走。你在老橡树根下坐了三天三夜，像要把它守住。可树不听你的，风也不听你的，连你自己也知道，有些东西，守不住。", "你站起来，腿麻了半天。你回头看了它一眼，它还在那儿，像一个等了很多年的老人。你没能道别，转身走了。"]}, "7": {"ritual": "在林子里点一盏不灭的灯", "ritualNote": "神话之境，是让自己成为这片林子认得的那盏灯——你走了，光还在。", "omens": ["你梦见自己站在老橡树的位置——不，你梦见自己就是那棵老橡树。风从你身上穿过，鸟在你枝上筑巢。", "你醒来时，手心攥着一粒橡子。不知道是什么时候放进去的。"], "success": ["你回到老橡树根下，把那粒橡子种进土里。你坐在旁边，看了一夜。第二天清晨，你站起来，拍了拍手上的土，走出林子。", "你走的时候，风里传来一声很轻的、像松涛一样的声音——不是道别，是应你。你低着头，走进阳光里。神话之境，在你种下那粒橡子的时候，成了。"], "fail": ["你把橡子种下去，可它没有发芽。你等了一个月，两个月，土里什么也没有。", "你蹲在那粒橡子旁边，想了很多。最后你把它挖出来，换了个地方，重新种下去。你看着那捧新土，想：'等得起。'"]}};

BREAKTHROUGH_V49.byJob["魔法师"] = {"guardian": {"tutor": {"name": "元素系教授", "bonus": 10, "rescue": 60, "desc": "在元素试炼塔执教二十年的老教授，袖口永远有灼痕。"}, "senior": {"name": "高年级元素使", "bonus": 6, "rescue": 40, "desc": "比你早三年入学的学长，最擅把元素搓成不炸的球。"}, "friend": {"name": "学院挚友", "bonus": 4, "rescue": 30, "desc": "知道你所有的糗事，也信你能成。他帮不上太多，但他在。"}}, "place": {"sacred": {"name": "元素试炼塔", "bonus": 8, "crisis": -8, "desc": "学院的尖塔。塔里每一层风都不一样，据说塔顶能听见魔网的脉搏。"}, "safe": {"name": "学院静室", "bonus": 5, "crisis": 0, "desc": "禁书区旁的小隔间。墙上有历代学生刻下的元素回路，磨得发亮。"}, "wild": {"name": "城北荒野", "bonus": -5, "crisis": 10, "desc": "无人打扰，也无人照应。风大，元素躁动，正合你的性子。"}}, "crises": [{"id": "mage_mana", "title": "法力失控", "text": ["最担心的事还是来了。体内的元素忽然不听使唤，顺着经脉一路烧上来，指尖先冒了青烟，接着整条手臂都在发抖。你听见血液在耳里涌，像涨潮。"], "opts": [{"id": "a", "t": "硬压——把失控的力量按回丹田", "stat": "SPR", "pass": ["你咬破舌尖，以痛为锁，一寸一寸把那团乱窜的元素逼回丹田。它在你胸口撞了三下，终于安静了。", "手掌上留下一道青痕，像一枚新烙的印。"], "fail": ["你压得越狠，它反弹得越凶。青火从指尖蹿到肩头，你整个人都在抖，最后被同门从火里捞出来。"]}, {"id": "b", "t": "呼救护法——让他用外力替你镇住", "stat": "CHA", "pass": ["护法的手按在你后心，一股沉稳的力量顺着脊柱淌下来，像雪水浇在烧红的铁上。失控的元素一层层退去，你听见他松了口气：'还行，没烧到脑子。'"], "fail": ["护法冲上来时已经迟了半步。你的左臂被烧得焦黑，他把你扛到窗边通风，一句话也没说，只是眼神很沉。"]}, {"id": "c", "t": "顺势放掉——把力量引向地面", "stat": "AGI", "pass": ["你不再硬抗，顺着那股力往地下一引。青火贴着地面窜开，在地上烧出一圈焦纹，像一页写满又擦掉的草稿。力量放空了，你瘫坐在地，人还在，境界也还在。"], "fail": ["你引偏了方向。青火燎上窗棂，惊动了整条走廊。事后你赔了学院的窗，还挨了老教授一记戒尺。"]}]}, {"id": "mage_omen", "title": "异象引觊觎", "text": ["破境到一半，塔外的天色暗了一层。有人看见你头顶凝出的元素光晕——消息传得比风快。夜里，你隐约觉得窗外的黑暗里多了一双眼睛，不是人的眼睛。"], "opts": [{"id": "a", "t": "不动声色，把异象收敛成灯芯那么小", "stat": "INT", "pass": ["你把外泄的元素光一点点收回来，敛成灯芯上的一粒青火。窗外的眼睛盯了许久，终没看出破绽，退了。", "次日清晨，塔底的石阶上多了一枚铜钱——有人在试探你的底细。"], "fail": ["你收得急了，光晕反而炸开一瞬，像在夜里放了一盏灯。窗外的眼睛记住了你。往后半月，你总觉得被人跟着。"]}, {"id": "b", "t": "迎出去——让想看的人看个够", "stat": "STR", "pass": ["你推开窗，把青火托在掌心，向黑暗里亮了亮。黑暗沉默了很久，最后传来一声轻笑：'有意思。'那气息退走了，留下半句低语：'魔网记得你了。'"], "fail": ["你迎出去时，黑暗里什么也没有。可你的名字还是出现在了不该出现的名单上。老教授后来只说了句：'锋芒不是这样用的。'"]}, {"id": "c", "t": "靠护法遮掩——让他把门守严", "stat": "CHA", "pass": ["护法往门口一坐，把佩剑横在膝上，谁来看都只看见一扇关紧的门。异象在门里散尽，门外的人讨了个没趣。", "破境结束后，护法拍拍你的肩：'下次动静小点。'"], "fail": ["护法守住了门，却没守住天。塔顶的异象还是被城里的某个存在看见了。你知道，有些视线，躲得过一时，躲不过一世。"]}]}, {"id": "mage_abyss", "title": "深渊低语", "text": ["破境至紧要处，你忽然听见一个声音——很轻，像有人贴着你的耳根说话。它说：'元素是你的，法则也是你的。为什么不走得更快一点？'你认得这声音的来处。它不在塔里，在更下面。"], "opts": [{"id": "a", "t": "充耳不闻，把心神钉在仪式上", "stat": "SPR", "pass": ["你默念学院的第一条戒律，把那声音当作风声。它说了三遍，见你不应，悻悻地退了。你听见自己心里那根弦，松了一格。", "塔底某处，好像有什么东西翻了个身。"], "fail": ["你想不听，可它太会挑地方说了。就在你心神松动的那个刹那，它钻进来半个字。那半个字在你脑海里留了三天，像一根拔不掉的刺。"]}, {"id": "b", "t": "回它一句——'我走我的路'", "stat": "INT", "pass": ["你开口，声音不高不低：'我走我的路。'那声音静了很久，最后说：'有趣。'然后真的退了。你第一次觉得，和深渊说话，也没那么可怕——可怕的是怕它。"], "fail": ["你回了一句，它却更来劲了。它开始讲你小时候的事，讲得一字不差。你一身冷汗，再也静不下心。护法发现你脸色不对，强行中断了仪式。"]}, {"id": "c", "t": "让护法替你守着心神", "stat": "CHA", "pass": ["你把手按在护法肩上，让他把一件旧物塞进你怀里——是学院发的校徽。那声音见了校徽，像见了脏东西，呸了一声，退了。", "旧物的好处是，它记得你是谁。"], "fail": ["护法替你挡了一记，心神却也被那声音蹭了一下。他扶着墙，脸色发白：'这东西……比传闻里更会说话。'你欠了他一份大人情。"]}]}], "1": {"ritual": "第一次让元素听你的话", "ritualNote": "初阶法师凝元，不过把散乱的元素聚拢成自己的形状。", "omens": ["夜里你睡得正沉，忽然觉得手心发烫。睁开眼，油灯的芯上跳着一粒青色的火——你分明没有点它。它在你掌心里滚了一圈，像只认路的雀，又缩回灯芯里去了。", "第二天上课，老教授多看了你一眼。他没说什么，只在课后留了一句：\"最近别睡太沉。\""], "success": ["你盘坐在静室中央，把那粒青火从灯芯里唤出来。这一次它没有缩回去，顺着你的指节爬了一圈，在你掌心里落下，像一枚印章。你握了握拳，掌心的温度刚好。", "凝元，成了。"], "fail": ["你试着去唤那粒青火，它却炸开在指尖，燎出一串水泡。老教授隔着门说了句：\"急了。\"他顿了顿：\"元素这东西，急不得。\""]}, "2": {"ritual": "元素的脾气", "ritualNote": "中阶法师化意，是摸清每一种元素的脾气，然后跟它们交朋友。", "omens": ["你最近对水的感知越来越怪。倒茶的时候，杯里的水会先停一下，再落进杯底——像在等你点头。", "你试着朝那杯水点了点头。它落下去的时候，比平时慢了一点。"], "success": ["你闭着眼，把一盆水从盆里\"请\"出来，让它在半空走了一趟你走过的路。水落下时没有溅起一滴。你睁开眼，看见水面映着你的脸，比镜子里的更像你自己。", "化意，成了。"], "fail": ["水在半空散了，泼了你一身。你听见自己的呼吸，很重，像被什么压着。盆里的水在你看不见的地方，悄悄笑了一声。"]}, "3": {"ritual": "一场公开论证", "ritualNote": "高阶法师晋宗师，要在同侪与学者面前证明一条自己的法则——这是学院的老规矩。", "omens": ["论证会的名单贴出来那天，你的名字在最上面。老教授把一支旧羽毛笔递给你：\"用它写。笔比法杖诚实。\"", "笔尖上沾着一滴干了的墨，不知是哪一代法师留下的。你握着它，忽然觉得手心里那团青火躁动起来，像在替你紧张。"], "success": ["你在满堂学者面前写下那条法则，笔尖落定的刹那，礼堂里的油灯齐齐暗了一瞬——又同时亮起。有人倒吸一口气，老教授在台下，慢慢点了点头。", "你听见魔网深处传来一声极轻的应和，像有人隔着很远，跟你碰了一下杯。"], "fail": ["论证到一半，你的法则在众人面前裂了。公式在纸上爬成一片乱麻。老教授没有骂你，只是把那支旧笔收了回去：\"回去再想。想清楚了，笔还在。\"", "你在满堂的眼底走下台，掌心的青火，第一次显得烫手。"]}, "4": {"ritual": "法则入卷", "ritualNote": "大宗师之境，要把毕生所证写成一卷可以传世的法则书——不是为后人，是为自己。", "omens": ["你开始梦见一张空白的长卷。梦里你提笔写下第一行，字迹便像活物一样顺着纸面爬开，爬成山川、河流、风向，爬成你走过的所有路。", "醒来时，枕边多了一根羽毛——不是你屋里的任何一支笔上掉下来的。"], "success": ["你闭关七日，把那条法则从头到尾证了一遍。落笔时，纸面上的字真的动了起来，爬成一幅图——是你的手印。你把手覆上去，图纹亮起，又淡去，像认了主。", "法则入卷，成。"], "fail": ["你写了撕，撕了写。第七日，纸面烧了起来，火是青色的，跟你掌心的那粒火一样。你看着它烧完，忽然明白：这一卷，还不到该写的时候。"]}, "5": {"ritual": "改写一条规则", "ritualNote": "传奇之境，是让一条现成的法则因你而变——小到一枚火球的形状，大到一条河流的方向。", "omens": ["你路过城北的河，河水在你脚边打了个旋。你蹲下去，把手伸进水里——河水在你手心里分了一瞬，又合拢。两岸的柳树，齐齐朝你弯了一下腰。", "老教授的信在傍晚送到，只有一行字：\"想好了再改。河会记得你。\""], "success": ["你在河边坐了三天三夜。第四天清晨，你把手伸进河水，这一次，河水没有合拢。它沿着你划出的新道流了半里，才徐徐回到旧路。", "两岸的柳树，这一次没有弯腰。它们只是安静地看着，像在看你做了什么。你听见河在你身后，用新河道的声音，哼了一句从前的调子。"], "fail": ["你改动了河水，却忘了水的性子。它顺着新道流了半里，忽然回头，把你冲了个踉跄。你浑身湿透地站在岸上，河在你面前恢复原样，像什么都没发生。", "只有你裤脚上的泥知道，你确实试过。"]}, "6": {"ritual": "与魔网对话", "ritualNote": "半神之境，是第一次真正听见魔网的声音——不是听它说话，是听它沉默。", "omens": ["那夜你梦见自己站在一张无边的大网中央，每一根丝上都系着一盏灯。你的那盏灯，在很远的边缘，忽明忽暗。", "你伸手去碰那根丝，整个网都颤了一下。梦外，你睁着眼躺了一夜，掌心的青火一夜未灭。"], "success": ["你不再说话，只是坐在网中央。魔网也没有说话。你们就这样对坐了很久，久到网上的灯一盏一盏亮起，又一盏一盏熄灭。", "最后，它偏了一根丝——像人偏了一下头，让你看清楚自己的位置。你醒来时，掌心的青火里，多了一丝银纹。"], "fail": ["你想抢着说话，魔网却在你开口的瞬间退远了。灯一盏一盏灭下去，只剩你脚下那一盏，孤零零地亮着。", "你站在原地，第一次尝到\"渺小\"的味道——不是坏事，只是很冷。"]}, "7": {"ritual": "在魔网上刻名", "ritualNote": "神话之境，是把自己的名字刻进魔网本身——从此你存在的每一刻，都在改写这个世界。", "omens": ["你又梦见那张网了。这一次，网的中央空着一格——像是从开天辟地起，就专门给你留的。", "梦里的你低头看了看自己的手。掌心的青火已经不再是火，是一枚细小的、亮着的字。你还没看清那是什么字，就醒了。"], "success": ["你不再尝试，只是把手按在那一格空位上。指尖触到的瞬间，整张网亮了起来——像整片大陆的灯同时被点亮。你的名字在网中央亮起，又淡去，像水面的月。", "从此，你走过的每一寸土地，都记得你的名字。你听过魔网深处的风，也听过它低低地，唤你的名字。"], "fail": ["你按不下去。那一格空位像烧红的铁，烫得你缩回了手。网没有嘲笑你，只是安静地等——它有的是时间。", "你醒来时，掌心的字已经淡了。可你知道它还在，等一个更合适的日子。"]}};
BREAKTHROUGH_V49.byJob["灵魂法师"] = {"guardian": {"tutor": {"name": "墨丘利·星辰之眼", "bonus": 10, "rescue": 60, "desc": "灵魂魔法教授、前执灯人。他的眼睛能看见你灵魂里没说完的话。"}, "senior": {"name": "通灵学长", "bonus": 6, "rescue": 40, "desc": "在灵界走过三回的人。话少，眼神深，从不跟人谈他看见过什么。"}, "friend": {"name": "学院挚友", "bonus": 4, "rescue": 30, "desc": "全学院唯一敢在深夜敲你门的普通人。他说：'你的秘密我不看，你的人我认得。'"}}, "place": {"sacred": {"name": "灵法塔·观星层", "bonus": 8, "crisis": -8, "desc": "塔顶有一面从不落灰的旧镜。镜面不映人，映人的灵魂。"}, "safe": {"name": "禁书区小室", "bonus": 5, "crisis": 0, "desc": "书架间的夹层，坐垫上留着历代修者磨出的凹痕。"}, "wild": {"name": "城郊墓地", "bonus": -5, "crisis": 10, "desc": "安静，也阴冷。灵界与现实的帘子，在这里薄得像一层纸。"}}, "crises": [{"id": "soul_face", "title": "直面本心", "text": ["破境至深处，你忽然站在了自己的灵魂里——对面站着一个人，穿着你的衣服，长着你的脸，却比你更安静。它看着你，像看着一个迟到很久的客人。墨丘利说过，这一关躲不掉，只能\"认\"。"], "opts": [{"id": "a", "t": "认——它就是你的一部分", "stat": "SPR", "pass": ["你朝它点了点头。它愣了一下，然后笑了——那笑容里有你所有没对别人说过的委屈和骄傲。它向前一步，融进你身体里。你觉得自己完整了一点。", "对面空了。你站在原地，第一次觉得心里亮堂。"], "fail": ["你想认，却认不出口。它等了很久，最后说：'你还没准备好。'你从灵魂深处退出来时，满身冷汗，心里空了一块。"]}, {"id": "b", "t": "问它——你是什么时候开始藏起来的", "stat": "INT", "pass": ["它想了想，说：'从你第一次说谎那天。'你没有反驳。它又补了一句：'不过你说谎，是为了不伤别人。这我替你说过情。'你笑了，它也笑了。这一次，它自己走了回来。"], "fail": ["它不答，只是看着你。你看懂了那个眼神：你连它什么时候藏的都不知道，凭什么说自己了解自己。", "你败下阵来，退出去时，手还在抖。"]}, {"id": "c", "t": "让它走——不认，也不赶", "stat": "CON", "pass": ["你看着它，说：'你走吧。'它没动。你说：'我不赶你，也不认你。你愿意站这儿，就站着。'它站了一会儿，慢慢隐去了。", "后来你发现，它其实一直没走——只是不再躲了。"], "fail": ["它不肯走。你越是要它走，它越是贴得近。最后你几乎是逃出那个地方的。", "墨丘利在门外看着你，只说了一句：'你把它关在里面，它会敲门的。'"]}]}, {"id": "soul_debt", "title": "旧债敲门", "text": ["破境途中，你听见有人敲门。门外的声音很老，老得像从十几年前漏过来的。你认得那个声音——是你还不会说谎的年纪，欠下的一份人情。"], "opts": [{"id": "a", "t": "开门，把欠的还了", "stat": "CHA", "pass": ["你打开门，看见一个你几乎忘了的人。你还清了那份人情，不多，也不少。他走的时候，在你肩上拍了一下：'行了，两清。'", "你关上门，心里那块压了很久的石头，第一次挪开了。"], "fail": ["你想还，却发现自己还不起——那份人情早就涨了利息，是你当年没算到的。你欠得比原来更多，灰溜溜地退了回来。"]}, {"id": "b", "t": "不开门——破境要紧", "stat": "CON", "pass": ["你背过身，不去听。门敲了三夜，终于静了。破境成功了，可你心里知道，那份债还在门外，等一个更闲的日子。"], "fail": ["门敲了一夜，你一分也静不下来。灵魂法师的心，最怕的就是欠着。你没能破境，坐在原地，听着门外的声音，一夜没动。"]}, {"id": "c", "t": "请护法去应付", "stat": "CHA", "pass": ["护法替你开了门。他跟门外的人谈了一会儿，替你做了个约定。门关上时，护法把一张纸条塞给你：'下个满月，城东茶铺。'", "你欠他的人情，又多了一笔——可债主换了人，反而好谈。"], "fail": ["护法去开门，门外的人却只认你的声音。他隔着护法喊你的名字，一声比一声近。你最终没能躲过去。"]}]}, {"id": "soul_abyss", "title": "深渊低语", "text": ["灵魂之海深处，你听见一个比灵魂更老的声音。它不诱惑你，只是提醒：'你学的东西，名字里带'魂'字的，都是从这里借的。'你知道它没说谎。"], "opts": [{"id": "a", "t": "承认，但不借", "stat": "SPR", "pass": ["你说：'是借的。但我不签契。'那声音沉默了一会儿，低低地笑了：'你比你老师诚实。'它退了。你听见墨丘利在远处，轻地松了口气。"], "fail": ["你承认了，却没能守住那句'不借'。它在你心里留了一个影儿，不疼不痒，就是让你偶尔会想起它的话。"]}, {"id": "b", "t": "反问——你又是从谁那里借的", "stat": "INT", "pass": ["那声音愣了一下，像从来没人这样问过它。它没有回答，退得更深了。你听见它退走时，带起一片很远的回声。", "有些问题，深渊也答不上来。"], "fail": ["它不答，只是把你带进更深的地方。你在黑暗里走了很久才出来，出来时，眼神比进去时沉了一层。"]}, {"id": "c", "t": "让护法点灯", "stat": "CHA", "pass": ["护法在门外点起一盏灯。灯是普通的油灯，可那声音见了灯，像见了烫。它说：'你们学院的人，就爱坏规矩。'然后退了。", "有些东西怕灯，不是怕亮——是怕被看清。"], "fail": ["灯被那声音吹灭了。护法的手抖了一下，又点起来。这一次，他站到了你身边，一步没退。"]}]}], "1": {"ritual": "与自己的影子对视", "ritualNote": "灵魂学徒凝元，先从看得见自己的影子开始。", "omens": ["你最近总觉得有人在看自己——可四下无人。后来你发现，是你的影子在看你。它比你先一步转过头来。", "你试着朝影子笑了一下。它没有笑。它只是盯着你，像在确认什么。"], "success": ["你在镜前坐下，让影子走到镜子前面来。它站在你身后，第一次没有模仿你的动作。你转过身，朝它伸出手——它握住了你的手，凉的，像握着一截月光。", "凝元，成了。你不再是一个人照镜子。"], "fail": ["影子不肯上前。它缩在墙角，像在怕你。你试着叫它，它却越缩越小。", "墨丘利路过，看了一眼：'你连自己的影子都怕，怎么去听别人的灵魂？'"]}, "2": {"ritual": "听见一句没说出口的话", "ritualNote": "化意之境，是第一次听见别人藏在话底下的话。", "omens": ["食堂的厨娘问你今天的汤咸不咸。你听懂了——她今天心情不好，她的猫跑了。你愣了一下：你怎么听出来的？", "那之后，你开始听见很多没说出口的话。满学院都是心事，像深秋的叶子，落了一地。"], "success": ["你闭着眼，听窗外的风穿过走廊。风里裹着百十个人的心事，你不再句句都听，只挑最响的听。", "有一个声音在很远的地方说：\"谢谢。\"你不认识那个人，但他今晚会睡得安稳些。化意，成了。"], "fail": ["你听见了太多，脑子像被撑开。你在墙角坐了一下午，把那些不属于你的心事一件件还回去。", "还回去的时候，你听见其中一句说：\"其实我不怪你。\"你分不清那是谁的，只觉得很累。"]}, "3": {"ritual": "替一个陌生人守住秘密", "ritualNote": "宗师之境，不是听见更多，而是守住听见的。", "omens": ["你最近发现，知道得越多，话越少。食堂厨娘开始给你多盛一勺汤，她没说为什么，你也没问。", "有一天夜里，你听见一个从不认识的学生的秘密——关于他为什么要来学院。你听了，又把它放回原处，没让任何人知道。"], "success": ["那个学生毕业那天，在门口站了很久。他朝人群里看了看，没有找谁，只是鞠了一躬。", "你站在人群里，没有应。有些秘密，守住了就是守住了。宗师之境，就这样在无人知道的地方，成了。"], "fail": ["你听见了一个人的秘密，没忍住，在茶余饭后漏了半句。那半句传出去，伤了一个人。", "你花了一个月补救，补救回来了，可你知道，有些话出口了，就收不回原样。这一境，你没能晋。"]}, "4": {"ritual": "在灵界留下一枚脚印", "ritualNote": "大宗师之境，要去灵界走一趟——不带任何人，只带自己。", "omens": ["墨丘利在破境前夜把你叫去，递给你一枚铜铃：\"灵界不认路，认铃。\"", "铃是旧的，柄上磨得发亮，不知多少执灯人握过。你握着它，忽然觉得掌心发凉——那不是铜的凉，是另一个世界的凉。"], "success": ["你在灵界走了三天三夜。那里没有风，没有光，只有声音——很轻的、像从很远的地方传来的声音。你循着铃声走回来时，脚底沾着一层银灰色的灰。", "墨丘利看了看你的鞋底，点了点头：\"有人去过，和没人去过，不一样。\"你低头，看见那层灰里，有一枚脚印——是你的。大宗师，成了。"], "fail": ["你在灵界迷了路。铃声在左边响，你在右边走，怎么也走不到。第三天，你听见一个声音说：\"你还没准备好留脚印。\"", "你醒在灵法塔的旧镜前，镜面上全是灰，你的脚印，一枚也没有留下。"]}, "5": {"ritual": "听清自己灵魂的呼吸", "ritualNote": "传奇之境，是终于能听见自己灵魂的呼吸——而不是别人的。", "omens": ["你开始能分辨哪些心事是自己的，哪些是捡来的。你花了一个月，把捡来的那些一件件还回去。", "还到最后一夜，你坐在静室里，四周忽然安静了。不是没有声音，是你终于听不见别人的了。"], "success": ["你听见了。很轻，像风穿过门缝——那是你自己的灵魂在呼吸。它不急不缓，比你想象中更稳。你把手按在胸口，它停了一拍，又继续，像在回应你。", "传奇之境，成了。你终于不是靠别人的心事活着了。"], "fail": ["你听不见。四周太安静了，安静得你分不清那是空，还是你自己的呼吸本来就这么轻。", "你在静室里坐到天亮，什么也没等到。出来时，墨丘利看了你一眼：\"你太急着听，反而听不见。\"你承认他说得对。"]}, "6": {"ritual": "与深渊的倒影对话", "ritualNote": "半神之境，要去见自己灵魂深处的深渊倒影——不是战胜它，是认识它。", "omens": ["你又梦见那片灵魂之海了。海面平静得像镜子，可你知道，镜子底下有东西。", "墨丘利最后一次来找你，没有带任何东西。他站在门口，看了你很久，只说了一句：\"回来的时候，别只带一半自己。\""], "success": ["你站在海面上，低头看水里的倒影。倒影也在看你。你没有回避，它也没有回避。你们对视了很久，久到海面开始起雾。", "雾散时，倒影已经不见了——它走进了你脚下的影子里，像一滴墨落进砚台。你转身往回走时，墨丘利还在门口。他说：\"全回来了。\"你点了点头。"], "fail": ["你盯着倒影看了太久。它忽然伸出手，把你拽进了水里。你在海里挣扎了很久，摸到一只手——是墨丘利的。他把你的上半身拉出水面，你自己把下半身挣了出来。", "你浑身湿透地坐在岸边，发现自己丢了一小片影子。墨丘利没有责备你，只是说：\"会回来的。跟丢了的影子，就跟丢了的债一样，都会回来敲门。\""]}, "7": {"ritual": "把自己写进灵界的名单", "ritualNote": "神话之境，是让灵界记住你的名字——从此你走过的地方，死去的灵魂都会为你让路。", "omens": ["你在梦里听见有人念你的名字。声音很轻，像从灵界深处传来。你数了数，一共念了三遍——那是灵界的规矩，三遍，是记名。", "你醒来时，枕边放着一枚银灰色的灰。你知道那是什么：灵界还你的一枚脚印。"], "success": ["你站在灵界入口，没有带铃，没有带灯，只带自己的名字。你走进黑暗里，黑暗为你让开了一条路。", "你走完那条路，在路的尽头签下自己的名字。笔尖落下时，整片灵界的灰都亮了一瞬，像有人远远地、为你点了一盏灯。"], "fail": ["你在黑暗里走了很久，发现自己在绕圈。你的名字没有被记下——因为你走的路，不够长，也不够深。", "你退回人间时，掌心里还攥着那枚银灰。它不是你的脚印，是灵界还你的一份\"未完成\"。你知道，它会在某个更深的夜里，再敲门。"]}};
BREAKTHROUGH_V49.byJob["术士"] = {"guardian": {"tutor": {"name": "魔械学院老师傅", "bonus": 10, "rescue": 60, "desc": "在工坊里锤了四十年的老匠人。他不用看图纸，听声音就知道铸件哪里不对。"}, "senior": {"name": "造物师兄", "bonus": 6, "rescue": 40, "desc": "造出过会自己走路的铜雀。他常说：'造物之前，先造自己。'"}, "friend": {"name": "学院挚友", "bonus": 4, "rescue": 30, "desc": "总是把你的失败作品当宝贝收着。他说：'这些都是你。'"}}, "place": {"sacred": {"name": "魔械学院·熔火工坊", "bonus": 8, "crisis": -8, "desc": "地下的老工坊，炉火四十年没熄过。墙上的工具每一件都有名字。"}, "safe": {"name": "工坊侧室", "bonus": 5, "crisis": 0, "desc": "堆满旧图纸的小间。角落里有一张你学徒时坐过的凳子。"}, "wild": {"name": "铁匠铺后院", "bonus": -5, "crisis": 10, "desc": "露天打铁，火星子乱蹦。没有规矩，也少有人看。"}}, "crises": [{"id": "sorc_forge", "title": "造物反噬", "text": ["破境进行到一半，你体内的血脉忽然与炉火起了共鸣——火苗蹿起来，烧向你正在淬炼的那件作品。你听见金属在火里发出尖啸，像在求救，又像在警告。"], "opts": [{"id": "a", "t": "护住作品——先灭火", "stat": "INT", "pass": ["你抢在火苗吞没它之前，把作品从炉上抢了下来。手上燎出一串泡，但东西保住了。它在你手里发烫，像一只被你救回来的幼鸟。", "你低头一看，它似乎比你原先设计的，多了一道纹。"], "fail": ["你扑得太急，把作品碰翻在地。火苗卷上去，它在你眼前化成一滩铁水。你蹲在地上，看着那滩铁水慢慢凉掉，一句话也说不出来。"]}, {"id": "b", "t": "引火入身——让血脉替它分担", "stat": "CON", "pass": ["你摊开手掌，让炉火顺着血脉烧进体内。疼，像有人用铁签在你骨头上写字。但火在你体内走了一圈，竟真的静了。", "你吐出一口浊气，掌心多了一道火纹，像烫上去的印章。作品在你面前徐徐转了一周，像认了你。"], "fail": ["你引火入身，烧过了头。血从你鼻子里涌出来，你眼前一黑，差点栽进炉里。护法一把拽住你，火才从你身上退走。"]}, {"id": "c", "t": "喊护法断火", "stat": "CHA", "pass": ["护法抄起墙边的旧锤子，一锤砸在炉膛的闸门上。火熄了，满屋烟灰。你呛着咳了半天，发现作品还躺在砧上，完好无损。", "老师傅的声音从门口传来：'下次记得，火可以重来，人不行。'"], "fail": ["护法断火断晚了半步。作品还是裂了一道缝，不深，但看得见。你用錾子修了半夜，那道缝最后成了作品身上的一条纹路。"]}]}, {"id": "sorc_rival", "title": "仇人上门", "text": ["你在工坊里破境，炉火把整条街都映红了。半夜，有人砸门——是你早年在行当里结下的对头，闻着铁味寻上门来。"], "opts": [{"id": "a", "t": "不开门，让护法挡着", "stat": "CHA", "pass": ["护法横在门前，一句话没说，把门闩按住了。门外的砸门声由高到低，最后骂骂咧咧地远了。", "破境没受打扰，可你知道，这梁子又深了一层。护法看你一眼：'记着，躲过的仇，迟早要还。'"], "fail": ["护法挡了前门，那人却从后院翻进来了。你被迫中断破境，跟他打了一场。打赢了，境界也没了。"]}, {"id": "b", "t": "开门迎出去——用新火跟他了结", "stat": "STR", "pass": ["你推开门，掌心的炉火亮着。那人退了一步，又站住：'你以为晋了级我就怕你？'你举起手，火在你掌心里转了一圈，又收了回去：'不是怕不怕的事。是我没空。'", "他盯了你很久，最后哼了一声，走了。有些仇，亮个相就够了。"], "fail": ["你迎得太急，炉火还没稳住，被他抓住破绽，一记闷棍敲在肩头。你退进工坊，护法掩上门，破境彻底泡汤。"]}, {"id": "c", "t": "以火对火——比一场", "stat": "CON", "pass": ["你把他让进工坊，两人隔着炉子站定。你说：'三锤定音，谁输了谁走。'他应了。第三锤，你炉里的火比他的旺了一线。他收了锤子，转身走了。", "你关上门，才发现手在抖。可境界，稳住了。"], "fail": ["你输了那一锤。他的火压过你的，你听见自己心里那根弦'当'地一声，断了半根。他得意洋洋地走了，你在工坊里坐到天亮。"]}]}, {"id": "sorc_abyss", "title": "深渊低语", "text": ["炉火最旺的时候，你听见炉膛深处有声音——不是火声，是人声。它说：'你造的东西，迟早会取代你。你甘心吗？'你认得这声音的味道，它从更深的什么地方渗进来，顺着炉烟。"], "opts": [{"id": "a", "t": "往炉里添一铲好煤——用火声盖过它", "stat": "INT", "pass": ["你添了一铲煤，火声盖过了那声音。它不甘心，又说了两句，你听见炉火把它们烧成了灰。", "第二天，你在炉灰里拣出一块亮晶晶的渣。不是铁，不是煤，是那声音留下的一点残屑。你把它扔进废料桶，像处理一件用坏的模具。"], "fail": ["火声没能盖住它。它越说越近，你手里的钳子越握越紧。最后你熄了炉火，坐到天亮，那声音才退去。"]}, {"id": "b", "t": "回它——'我造的东西，是我的手'", "stat": "SPR", "pass": ["你对着炉膛说：'我造的东西，是我的手。手不会取代人，手就是人。'那声音静了很久，最后从炉缝里溢出来一声笑，像炉渣崩裂：'有意思。你比你会造的那些铁疙瘩，更知道自己在说什么。'它退了。"], "fail": ["你回了一句，它却缠了上来。那一整夜，你的手都在按图样，可画出来的全不是你的笔迹。天亮时你撕了图纸，声音才散。"]}, {"id": "c", "t": "让护法往炉里添一根圣木", "stat": "CHA", "pass": ["护法往炉膛里添了一根熏过的松木。火苗窜高的时候，那声音被冲散在松脂味里。它最后说了句：'你们学院的人……'就没声了。", "圣木烧完，炉膛里干干净净。你继续破境，像什么都没发生过。"], "fail": ["圣木烧起来了，可那声音不怕。它在烟里打了个滚，又钻回炉缝。你折腾到后半夜，才勉强稳住心神。"]}]}], "1": {"ritual": "第一件属于自己的作品", "ritualNote": "学徒凝元，要亲手造出第一件会记住你的作品——哪怕只是一枚铁钉。", "omens": ["你最近打铁格外顺手。同一把锤子，同样的火候，打出来的东西却比从前多了一分'活气'——像它们认得你手里的力道了。", "老师傅看了一眼你打的铁钉，没说话，把它别在了围裙口袋里。"], "success": ["你打了一枚铁钉，把它放在砧板上。你退后一步，默念你的名字——铁钉在砧板上转了转一下，像在应你。", "你捡起它，指腹上还留着它的温度。凝元，成了。你有了第一件'记得你'的作品。"], "fail": ["铁钉打好了，却怎么也不理你。你叫了它三遍，它纹丝不动。老师傅路过，把那枚铁钉收走了：'它还没准备好认你，你也没准备好当它的主。'", "你看着砧板上的灰，第一次知道造物这条路，急不得。"]}, "2": {"ritual": "造一件会呼吸的东西", "ritualNote": "化意之境，是让作品不再只是死物——它会呼吸，虽然很轻。", "omens": ["你开始给作品留'气口'——不是通风口，是你也说不上来的东西。老师傅看你改的图纸，看了很久，说：'你这不是在造东西，是在养东西。'", "那天夜里，你在工坊听见一声极轻的'呼——'，像什么活物在喘气。你找了半天，发现是你白天做的那只铜雀。"], "success": ["你把铜雀放在窗台上，它在你手心歪了歪头。你退开一步，它扑棱了一下翅膀——没飞起来，但你知道，它快了。", "化意，成了。你的作品第一次'呼吸'，比你自己喘的那口气，还让你高兴。"], "fail": ["你给铜雀留了气口，它却只是'嗤嗤'地漏风，像个漏气的皮囊。你拆了装，装了拆，最后把它收进抽屉里。", "老师傅看了一眼：'急了。造物和养孩子一样，气口留太早，孩子养不活。'"]}, "3": {"ritual": "让作品自己走一步", "ritualNote": "宗师之境，是让造物第一次'自己动'——不是机关，是它自己想动。", "omens": ["你梦见自己造了一只铁手，它在你睡着的时候，自己从架子上走下来，替你把被子掖好。", "你醒来时，架子上那只铁手的位置，确实偏了一寸。"], "success": ["你花了三个月，把那只铁手造出来。它不是靠机关动的——你给它装了一颗用你血脉淬过的心。它在你面前，自己抬了一下手指。", "就这一下，你蹲在工坊里笑了半天。老师傅在门口看了你一会儿，转身走了，围裙口袋里那枚铁钉，叮当响了一声。宗师，成了。"], "fail": ["铁手不动。你试了各种办法，它像一块真正的铁那样沉默。你把它拆了，零件摊了一桌。", "夜里你听见桌上窸窣响——你爬起来，看见那堆零件自己拼了拼，又停了。它想动，但还差一口气。你知道，那一口气，在你身上。"]}, "4": {"ritual": "锻出第一缕'自己的想法'", "ritualNote": "大宗师之境，不是造出会动的东西，而是造出会'想'的东西——哪怕只是一念。", "omens": ["你的铁手开始有自己的小动作了。你明明没让它抬手，它会在你看书时替你翻一页。", "老师傅看见了，沉默了很久，说：'你养的东西，开始有自己的想法了。这是好事，也是祸事。'"], "success": ["你不再给它设指令，只是每天跟它说说话。有一天，它在你不在的时候，自己拿起了锤子，敲了三下——力道、节奏，都是你的习惯。", "你站在门口看了很久，没有进去。那一瞬间你明白了：造物的最高境界，不是复制自己，是它长成了自己的样子。大宗师，成了。"], "fail": ["你想要它'想'，它就偏不想。你越是给它的脑子里塞图纸，它越是迟钝得像一块废铁。", "你拆开它的头，发现里面乱成一团。你花了一个月理清，理完之后，它还是原来的它——你没能让它多出那一念。"]}, "5": {"ritual": "把一件造物修得比原来更好", "ritualNote": "传奇之境，是修好一件'公认修不好'的东西——不只是手艺，是它认你。", "omens": ["老师傅把那件东西交给你时，没有多说，只放在你桌上。那是一盏老掉牙的铜灯，灯身裂了一道缝，从灯口一直裂到底。", "学院里没有人修得好它。老师傅说：'它是上一代术士的东西，脾气大。你试试。'"], "success": ["你修了四十九天。最后一天，你把裂缝用你的血脉熔合，没有用一滴焊锡。铜灯在炉火里亮起来时，裂缝处生出一道新的纹路，像树疤，也像胎记。", "你把它放回老师傅桌上。他没有看灯，先看了你：'你修的不是灯，是你自己。'传奇之境，在那盏灯亮起的时候，成了。"], "fail": ["你修了四十九天，铜灯在第四十八天夜里裂得更开了。裂缝从灯口裂到底，像一道嘲笑。你把铜灯放回老师傅桌上，他没有责备，只说：'它还没准备好让你修，你也没准备好。'", "你把碎片收进围裙口袋。那一晚，你听着碎片在口袋里叮当地响，一夜没睡。"]}, "6": {"ritual": "造一件不为任何人用的东西", "ritualNote": "半神之境，是造一件纯粹为了'存在'的作品——不卖，不送，不展示。", "omens": ["你开始画一张图纸，画了又撕，撕了又画。老师傅从不问你画什么，他只是在你画图纸的时候，把炉火烧得更旺一点。", "那张图纸上的东西，没有人见过，连你自己也说不出它是做什么用的。"], "success": ["你把那件东西造出来了。它不大，不亮，不响，放在那里，像一块安静的石头。可你知道，它身上每一道纹，都是你心里那些说不出口的话。", "你没有给它起名字。它也不需要名字。半神之境，在你放下锤子的那一刻，成了。你造了一辈子'有用'的东西，这是第一件只为自己存在的。"], "fail": ["你造不出它。不是手艺不够，是你说不清它该是什么样子。你拆了装，装了拆，最后把图纸烧了。", "老师傅看着炉灰，说：'有的东西，得等你自己先想清楚，才造得出来。'你把锤子放回架子上，觉得它比以前沉了。"]}, "7": {"ritual": "把自己锻成一件作品", "ritualNote": "神话之境，是把自己当成最后一件作品来锻——一生的火，都要在这一炉里烧完。", "omens": ["你梦见自己躺在砧板上，炉火在你上方烧着。你没有害怕，只是看着火，像看一位老朋友。", "老师傅在破境前夜，把那枚收了很多年的铁钉还给了你：'它认得你。带上它。'"], "success": ["你走进炉火里，像走进一个老朋友的怀抱。火在你身上烧了一夜，没有伤你分毫——它认得你，像你认得它。", "天明时，你从炉里走出来，身上多了一道纹，像铁钉的纹路。你把那枚铁钉重新打了打，它在你手里，亮得像一枚小小的太阳。神话之境，成了。"], "fail": ["你没能走进火里。火在门口拦住了你，不烫，却也不让路。你坐在工坊门口，看着炉火一夜未熄。", "老师傅没有说话，只是把围裙口袋里那枚铁钉又放回了口袋。你知道，火还在等你——等一个更合适的日子。"]}};


function attemptBreakthrough(){
  const realm = (typeof S.realm==="number")?S.realm:0;
  if(realm>=8){ writePar("已达神话境界，无需突破。","hint"); return; }
  const target = (S.attrs&&S.attrs.SPR?S.attrs.SPR:50)+realm*5;
  const roll = Math.floor(Math.random()*100)+1;
  let resultText = "";
  if(roll<=target){
    S.realm = realm+1;
    const realmNames = ["凡人","启灵","凝元","化意","宗师","大宗师","传奇","半神","神话"];
    S.maxHp += 20; S.hp = S.maxHp;
    S.maxMp = (S.maxMp||50)+10; S.mp = S.maxMp;
    resultText = "突破成功！晋升至【"+realmNames[S.realm]+"】境界！HP+20，MP+10。";
    addLog("突破至"+realmNames[S.realm]+"境界！","achievement");
  } else {
    S.hp = Math.max(1,S.hp-Math.floor(S.maxHp*0.1));
    resultText = "突破失败！走火入魔，损失10%最大HP。";
    addLog("突破失败，走火入魔。","combat");
  }
  // v30: 不自动关闭面板，显示结果+按钮
  const el = document.getElementById("cultivate-result");
  if(el){
    el.textContent = resultText;
    let actions = document.getElementById("cultivate-actions");
    if(!actions){
      actions = document.createElement("div");
      actions.id = "cultivate-actions";
      actions.className = "cultivate-actions";
      el.parentNode.appendChild(actions);
    }
    actions.innerHTML = "<button class='btn-gold' onclick='closePanel()'>返回游戏</button>";
  } else {
    writePar(resultText, roll<=target?"hint":"warn");
  }
  try{ v44_breakthroughFX(roll<=target); }catch(e){}
  renderTop(); renderStats();
}
